INSERT INTO public.casos (caso_id, usuario_id, antiguedad_usuario_dias, ciudad, vertical, restaurante, valor_orden_mxn, compensacion_solicitada_mxn, num_compensaciones_90d, monto_compensado_90d_mxn, entrega_confirmada_gps, tiempo_entrega_real_min, flags_fraude_previos, motivo_reclamo, descripcion_reclamo, recomendacion_agente, comp_ratio, comps_por_dia, monto_promedio_comp, gps_match_ok, entrega_demorada, es_sintetico, created_at, burn_rate, freq_densidad, flag_inconsistencia_gps, flag_mentira_gps_alta, flag_retraso_critico, flag_account_abuse, score_riesgo_previo, longitud_reclamo, flag_palabras_criticas, riesgo_ciudad, riesgo_vertical, gps_paradoja_score, sospecha_nuevo_recurrente, ratio_deviation, score_texto) VALUES ('COMP-SYN-0010', 'USR-SYN-0010', 190, 'Lima', 'Farmacia', 'El Rincón Colombiano', 342.48, 178.88, 1, 121.13, 'Señal perdida', 28, 0, 'Producto incorrecto', 'Estoy muy descontento con mi último pedido de delivery de El Rincón Colombiano ya que me trajeron una medicina que no era la que pedí. Me cobraron 342 pesos mexicanos por un producto defectuo y solo quiero una compensación de 179 pesos mexicanos por este error.', 'ESCALAR', 0.5223, NULL, NULL, NULL, NULL, true, '2026-07-29 01:02:21.920707', 0.637500, 0.011111, false, false, false, false, 0.50, 46, false, 0.0800, 0.2200, 0.0000, false, -2.0783, NULL);
INSERT INTO public.casos (caso_id, usuario_id, antiguedad_usuario_dias, ciudad, vertical, restaurante, valor_orden_mxn, compensacion_solicitada_mxn, num_compensaciones_90d, monto_compensado_90d_mxn, entrega_confirmada_gps, tiempo_entrega_real_min, flags_fraude_previos, motivo_reclamo, descripcion_reclamo, recomendacion_agente, comp_ratio, comps_por_dia, monto_promedio_comp, gps_match_ok, entrega_demorada, es_sintetico, created_at, burn_rate, freq_densidad, flag_inconsistencia_gps, flag_mentira_gps_alta, flag_retraso_critico, flag_account_abuse, score_riesgo_previo, longitud_reclamo, flag_palabras_criticas, riesgo_ciudad, riesgo_vertical, gps_paradoja_score, sospecha_nuevo_recurrente, ratio_deviation, score_texto) VALUES ('COMP-SYN-0013', 'USR-SYN-0013', 119, 'Bogotá', 'Comida', 'Parrilla Clásica', 135.80, 130.88, 9, 1649.73, 'NO confirmada', 59, 0, 'Cobro incorrecto', 'Soy un cliente del restaurante Parrilla Clásica que hice un pedido de entrega por un monto de $136 MXN. Resulta que en la entrega no se ajustó el cobro adecuadamente, ya que el monto que me cobraron fue $131 MXN más de lo que correspondía, y además la ruta GPS no fue confirmada con el tiempo de entrega de 59 minutos que había solicitado.', 'ESCALAR', 0.9638, NULL, NULL, NULL, NULL, true, '2026-07-29 01:02:21.920707', 13.863277, 0.100000, false, false, false, false, 4.50, 64, false, 0.0733, 0.5267, 0.0000, false, 1.2110, NULL);
INSERT INTO public.casos (caso_id, usuario_id, antiguedad_usuario_dias, ciudad, vertical, restaurante, valor_orden_mxn, compensacion_solicitada_mxn, num_compensaciones_90d, monto_compensado_90d_mxn, entrega_confirmada_gps, tiempo_entrega_real_min, flags_fraude_previos, motivo_reclamo, descripcion_reclamo, recomendacion_agente, comp_ratio, comps_por_dia, monto_promedio_comp, gps_match_ok, entrega_demorada, es_sintetico, created_at, burn_rate, freq_densidad, flag_inconsistencia_gps, flag_mentira_gps_alta, flag_retraso_critico, flag_account_abuse, score_riesgo_previo, longitud_reclamo, flag_palabras_criticas, riesgo_ciudad, riesgo_vertical, gps_paradoja_score, sospecha_nuevo_recurrente, ratio_deviation, score_texto) VALUES ('COMP-SYN-0006', 'USR-SYN-0006', 502, 'Lima', 'Comida', 'La Fonda Casera', 263.09, 243.93, 1, 349.66, 'SÍ - confirmada', 72, 1, 'Orden cancelada sin reembolso', 'Me comunicaron que mi pedido de la Fonda Casera fue cancelado sin que me hayan reembolsado el total del monto de la orden, me gustaría saber los motivos por los cuales no me devolvieron el dinero. El pedido fue entrega mediante GPS y el tiempo de entrega fue de 72 minutos.', 'APROBAR', 0.9272, NULL, NULL, NULL, NULL, true, '2026-07-29 01:02:21.920707', 0.696534, 0.011111, false, false, false, false, 2.50, 51, false, 0.0800, 0.5267, 0.7000, false, 0.9381, NULL);
INSERT INTO public.casos (caso_id, usuario_id, antiguedad_usuario_dias, ciudad, vertical, restaurante, valor_orden_mxn, compensacion_solicitada_mxn, num_compensaciones_90d, monto_compensado_90d_mxn, entrega_confirmada_gps, tiempo_entrega_real_min, flags_fraude_previos, motivo_reclamo, descripcion_reclamo, recomendacion_agente, comp_ratio, comps_por_dia, monto_promedio_comp, gps_match_ok, entrega_demorada, es_sintetico, created_at, burn_rate, freq_densidad, flag_inconsistencia_gps, flag_mentira_gps_alta, flag_retraso_critico, flag_account_abuse, score_riesgo_previo, longitud_reclamo, flag_palabras_criticas, riesgo_ciudad, riesgo_vertical, gps_paradoja_score, sospecha_nuevo_recurrente, ratio_deviation, score_texto) VALUES ('COMP-SYN-0011', 'USR-SYN-0011', 33, 'Puebla', 'Farmacia', 'Carnitas La Familia', 167.97, 97.40, 5, 645.20, 'NO confirmada', 57, 2, 'Orden no llegó', 'Me resulta muy frustrante que la orden que hice para Carnitas La Familia que era por $168 MXN no me llegó, esto demuestra total incompetencia en el servicio de delivery y por lo tanto me parece justo que me devuelvan mi dinero que asciende a $97 MXN.', 'RECHAZAR', 0.5799, NULL, NULL, NULL, NULL, true, '2026-07-29 01:02:21.920707', 19.551515, 0.151515, false, false, false, false, 6.50, 47, false, 0.0600, 0.2200, 0.2000, true, -1.6497, NULL);
