INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (193, 'COMP-0101', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad en la evidencia (GPS parcial, reclamo subjetivo) y flag de fraude previo requieren validación humana.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cuenta antigua con flag de fraude y GPS parcial. Reclamo por olor de comida sin evidencia objetiva.", "veredicto": "ESCALAR: ambigüedad en la evidencia (GPS parcial, reclamo subjetivo) y flag de fraude previo requieren validación humana.", "señales_explicadas": [{"peso": "alto", "señal": "Evidencia GPS parcial", "explicacion": "La ubicación no confirma ni descarta la entrega, generando ambigüedad."}, {"peso": "medio", "señal": "Flag de fraude previo", "explicacion": "1 flag de fraude en historial aumenta el riesgo de reclamos recurrentes."}, {"peso": "medio", "señal": "Reclamo subjetivo", "explicacion": "Olor a descompuesto es difícil de verificar sin fotos o evidencia adicional."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:18:04.687958');
