INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (30, 'COMP-SYN-0050', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por GPS no confirmada, alta densidad de reclamos (6 en 90d) y ratio de compensación alto (0.85) requieren validación manual de evidencia y patrón.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por no entrega con evidencia GPS ausente en cuenta antigua con alta frecuencia de reclamos y compensación elevada.", "veredicto": "ESCALAR: ambigüedad por GPS no confirmada, alta densidad de reclamos (6 en 90d) y ratio de compensación alto (0.85) requieren validación manual de evidencia y patrón.", "señales_explicadas": [{"peso": "alto", "señal": "GPS no confirmada", "explicacion": "No hay evidencia geolocalizada que valide o refute la entrega, impidiendo una decisión automatizada segura."}, {"peso": "medio", "señal": "Alta frecuencia de reclamos", "explicacion": "6 reclamos en 90 días en cuenta de 1789 días, sugiere posible uso excesivo aunque sin historial de fraude."}, {"peso": "bajo", "señal": "Ratio de compensación elevado", "explicacion": "Solicita $154.96 de $182 (85%), valor alto que justifica revisión pero no supera umbrales de rechazo automático."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:31:30.866657');
