INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (45, 'COMP-0003', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por flag de fraude previo, alta proporción de compensación y falta de evidencia GPS, requiriendo análisis humano para validar coherencia.', 'ambiguo: requiere análisis LLM', '{"resumen": "Solicitud de faltantes en cuenta con historial mixto y sin geolocalización, requiriendo validación humana por señales de riesgo moderado.", "veredicto": "ESCALAR: ambigüedad por flag de fraude previo, alta proporción de compensación y falta de evidencia GPS, requiriendo análisis humano para validar coherencia.", "señales_explicadas": [{"peso": "medio", "señal": "Flag de fraude previo", "explicacion": "1 flag de fraude en historial, indica riesgo moderado"}, {"peso": "medio", "señal": "Alta proporción de compensación", "explicacion": "comp_ratio=0.8975, cercano al umbral de abuso"}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "Sin evidencia geolocalizada para validar el estado del pedido"}, {"peso": "alto", "señal": "Ambigüedad operativa", "explicacion": "Reclamo de faltantes sin corroboración directa, requiere análisis LLM/humano"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:09:23.06396');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (200, 'COMP-0108', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por GPS perdido y frecuencia moderada requiere revisión humana y validación de pasarela de pagos.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por duplicidad de cobro con GPS no verificable y sin señales de fraude claro, pero con datos insuficientes para aprobación automática.", "veredicto": "ESCALAR: ambigüedad por GPS perdido y frecuencia moderada requiere revisión humana y validación de pasarela de pagos.", "señales_explicadas": [{"peso": "alto", "señal": "GPS señal perdida", "explicacion": "Imposibilita corroborar entrega o error operativo, generando incertidumbre técnica"}, {"peso": "medio", "señal": "Frecuencia moderada", "explicacion": "3 reclamos en 90d sin historial de fraude, requiere contexto adicional"}, {"peso": "medio", "señal": "Ambigüedad técnica", "explicacion": "Reclamo de cobro duplicado sin evidencia concluyente a favor o en contra"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:18:25.467885');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (81, 'COMP-SYN-0051', 'llm', 'RECHAZAR', 'RECHAZAR por análisis LLM: Cuenta nueva (42 días) con alta frecuencia de reclamos (6 en 90d). El patrón coincide con la regla de cuenta nueva con múltiples reclamos, lo que indica posible abuso.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por entrega no realizada en cuenta nueva con alta densidad de actividad y sin confirmación GPS.", "veredicto": "RECHAZAR: cuenta nueva con múltiples reclamos en corto tiempo, patrón sospechoso de abuso a pesar de no confirmar GPS.", "señales_explicadas": [{"peso": "alto", "señal": "Cuenta nueva con alta frecuencia", "explicacion": "antiguedad=42d, 6 reclamos en 90d"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "No hay evidencia geolocalizada que respalde la entrega, pero la frecuencia de reclamos es el factor determinante"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:31:52.017994');
