INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (107, 'COMP-0004', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y discrepancia entre estado de la app y evidencia técnica, requiere revisión humana.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por no recepción con señal GPS perdida y perfil de usuario sin historial de fraude. Datos insuficientes para decisión automatizada.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y discrepancia entre estado de la app y evidencia técnica, requiere revisión humana.", "señales_explicadas": [{"peso": "alto", "señal": "Señal GPS perdida", "explicacion": "La falta de datos de ubicación impide confirmar o refutar la entrega, generando insuficiencia de evidencia."}, {"peso": "medio", "señal": "Perfil de usuario limpio", "explicacion": "antiguedad=1158d, 0 flags fraude, 2 reclamos en 90d, sin señales de abuso."}, {"peso": "medio", "señal": "Discrepancia estado app vs evidencia", "explicacion": "La app marca entregado pero no hay GPS que lo respalde, requiriendo validación manual."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:09:41.058445');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (211, 'COMP-0117', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: alta frecuencia de reclamos y ratio de compensación elevado sin confirmación GPS requieren análisis manual para descartar abuso o validar inconsistencias.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por retraso y calidad de comida con alta frecuencia de solicitudes y sin evidencia GPS, generando ambigüedad que requiere revisión humana.", "veredicto": "ESCALAR: alta frecuencia de reclamos y ratio de compensación elevado sin confirmación GPS requieren análisis manual para descartar abuso o validar inconsistencias.", "señales_explicadas": [{"peso": "alto", "señal": "Alta frecuencia de reclamos", "explicacion": "6 reclamos en 90 días con ratio de compensación del 84.39%, indicando patrón de uso intensivo."}, {"peso": "medio", "señal": "Falta de evidencia GPS", "explicacion": "La entrega no fue confirmada por GPS, lo que impide validar la ubicación y el tiempo real de entrega para el reclamo por retraso."}, {"peso": "bajo", "señal": "Ambigüedad en justificación", "explicacion": "El reclamo menciona retraso y estado de la comida sin detalles específicos ni evidencia adjunta, requiriendo contexto adicional."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:19:04.85816');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (182, 'COMP-SYN-0054', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: requiere revisión humana por señal de ambigüedad y flag de fraude previo, a pesar de la coherencia general del reclamo.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por items incorrectos con compensación proporcional. Perfil antiguo y limpio en frecuencia, pero con 1 flag histórico y señal de ambigüedad que impide automatización total.", "veredicto": "ESCALAR: requiere revisión humana por señal de ambigüedad y flag de fraude previo, a pesar de la coherencia general del reclamo.", "señales_explicadas": [{"peso": "alto", "señal": "Señal de ambigüedad", "explicacion": "El sistema detecta ambigüedad y requiere análisis LLM para validar la coherencia del reclamo."}, {"peso": "medio", "señal": "Flag de fraude previo", "explicacion": "Usuario cuenta con 1 flag de fraude histórico que, aunque bajo el umbral de rechazo, justifica revisión."}, {"peso": "bajo", "señal": "Coherencia GPS y monto", "explicacion": "GPS no confirmada coincide con la afirmación del usuario; monto solicitado ($291) es proporcional al pedido ($446) y ratio de compensación (0.65)."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:32:32.667267');
