INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (49, 'COMP-SYN-0032', 'reglas', 'RECHAZAR', 'RECHAZAR por análisis LLM (score=0.85): Alta frecuencia de reclamos previos (8 en 90 días) en una cuenta con solo 13 días de antigüedad, combinado con pérdida de señal GPS y un monto de compensación desproporcionadamente alto (81% del valor del pedido), sugiere un patrón de abuso.', 'ambiguo: requiere análisis LLM | 8 reclamos en 90 días con solo 13 días de antigüedad de cuenta | Compensación solicitada (81%) desproporcionada vs valor del pedido | Pérdida de señal GPS durante la entrega | Descripción del reclamo confusa e inconsistente sobre la responsabilidad | Usuario nuevo con alta actividad de reclamos', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (50, 'COMP-0011', 'reglas', 'RECHAZAR', 'RECHAZAR por señales de fraude: flags_fraude_previos >= 2; score_riesgo_previo > 10.0.', 'flags_fraude_previos >= 2 | score_riesgo_previo > 10.0', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (54, 'COMP-0044', 'reglas', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (55, 'COMP-SYN-0001', 'reglas', 'APROBAR', 'APROBAR por análisis LLM (score=0.25): El reclamo es consistente en su narrativa con la pérdida de señal GPS y el tiempo de entrega corto, sin historial previo de reclamos ni flags, y el monto solicitado es proporcional al valor del pedido.', 'ambiguo: requiere análisis LLM | Señal GPS perdida durante la entrega | Tiempo de entrega reducido (26 min) | Monto solicitado menor al valor total del pedido | Antigüedad baja pero sin reclamos previos', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (56, 'COMP-SYN-0041', 'reglas', 'RECHAZAR', 'RECHAZAR por análisis LLM (score=0.95): La descripción del reclamo es una respuesta de un modelo de IA negándose a generar un texto de queja, lo que evidencia un intento de automatización fraudulenta.', 'ambiguo: requiere análisis LLM | descripción de reclamo generada por IA | alta frecuencia de reclamos previos (9 en 90 días) | señal de GPS perdida', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
