INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (230, 'COMP-0005', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: reclamo de discrepancia financiera en usuario sin historial de abuso que requiere validación manual del desglose de cargos y reconciliación.', 'ambiguo: requiere análisis LLM', '{"resumen": "Discrepancia de cobro en cuenta antigua y confiable. Sin señales de fraude, pero requiere revisión humana para validar el desglose de cargos.", "veredicto": "ESCALAR: reclamo de discrepancia financiera en usuario sin historial de abuso que requiere validación manual del desglose de cargos y reconciliación.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil confiable", "explicacion": "antiguedad=1458d, 0 flags fraude, 0 reclamos en 90d"}, {"peso": "medio", "señal": "Ambigüedad financiera", "explicacion": "Reclamo sobre monto cobrado vs resumen sin evidencia automática clara, requiere análisis LLM/manual"}, {"peso": "bajo", "señal": "GPS no determinante", "explicacion": "Señal perdida, pero el reclamo es de cobro, no de entrega"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:09:57.698681');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (212, 'COMP-0118', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con antigüedad superior a 3 años y 0 flags de fraude. Reclamo de cobro duplicado es un error operativo común y coherente. GPS con señal perdida no invalida la evidencia de facturación.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de cobro duplicado en cuenta limpia y antigua. Sin señales de abuso.", "veredicto": "APROBAR: reclamo legítimo de error de facturación en usuario con historial impecable.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario sano", "explicacion": "antiguedad=1106d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "medio", "señal": "Evidencia de cobro duplicado", "explicacion": "Monto solicitado coherente con error de sistema, sin inconsistencias de abuso"}, {"peso": "bajo", "señal": "GPS señal perdida", "explicacion": "Datos de ubicación no disponibles, pero no afectan la verificación de cobro"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:19:27.540932');
