INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (63, 'COMP-SYN-0090', 'reglas', 'APROBAR', 'APROBAR por análisis LLM (score=0.15): La diferencia reclamada es mínima ($15 MXN) y el usuario tiene antigüedad considerable con pocos reclamos previos, aunque la falta de confirmación GPS y un flag previo atenúan levemente la confianza.', 'ambiguo: requiere análisis LLM | Diferencia monetaria insignificante ($15 MXN) | Usuario con 416 días de antigüedad | Solo 2 reclamos en 90 días | Motivo declarado consistente con el vertical (farmacia/restaurante) | Flag de fraude previo (1) pero sin patrón claro de abuso', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (58, 'COMP-SYN-0058', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: GPS parcial y flag previo generan ambigüedad que requiere revisión humana para validar la evidencia y el contexto del reclamo.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por productos incorrectos con evidencia GPS incompleta y historial con un flag previo. Requiere validación manual.", "veredicto": "ESCALAR: GPS parcial y flag previo generan ambigüedad que requiere revisión humana para validar la evidencia y el contexto del reclamo.", "señales_explicadas": [{"peso": "alto", "señal": "GPS Parcial", "explicacion": "La ubicación no confirma ni descarta la entrega, creando ambigüedad sobre la validez del reclamo de productos incorrectos."}, {"peso": "medio", "señal": "Flag previo", "explicacion": "1 flag de fraude en historial, por debajo del umbral de rechazo automático pero requiere contexto adicional."}, {"peso": "bajo", "señal": "Perfil conservador", "explicacion": "Antigüedad de 1232d y 0 reclamos en 90d indican comportamiento de bajo riesgo."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:33:11.478997');
