INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (156, 'COMP-0016', 'llm', 'RECHAZAR', 'RECHAZAR por análisis LLM: Cuenta nueva (75d) con 6 reclamos en 90d, lo que activa la regla de cuenta nueva con múltiples reclamos. Patrón de alta frecuencia sin evidencia de error sistémico.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por error de cupón en cuenta nueva con alta densidad de solicitudes en corto tiempo.", "veredicto": "RECHAZAR: cuenta nueva con múltiples reclamos en 90d, patrón sospechoso según reglas de negocio.", "señales_explicadas": [{"peso": "alto", "señal": "Cuenta nueva con alta frecuencia", "explicacion": "antiguedad=75d, 6 reclamos en 90d, activa regla de sospecha"}, {"peso": "medio", "señal": "Ausencia de evidencia de error masivo", "explicacion": "comp_ratio=0.7942 y monto moderado sin indicadores de fallo operativo generalizado"}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "Falta de trazabilidad completa en la entrega, aunque el reclamo es de precio, reduce la confianza en la evidencia"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:10:41.055102');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (172, 'COMP-0119', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: se detectó señal de ambigüedad que requiere análisis LLM para validar la coherencia operativa y evitar riesgos de marca.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por cancelación operativa sin reembolso. Perfil conservador, pero se requiere análisis LLM para confirmar la validez.", "veredicto": "ESCALAR: se detectó señal de ambigüedad que requiere análisis LLM para validar la coherencia operativa y evitar riesgos de marca.", "señales_explicadas": [{"peso": "alto", "señal": "Ambigüedad operativa", "explicacion": "El sistema indica que se requiere análisis LLM para confirmar la validez del reclamo."}, {"peso": "medio", "señal": "Perfil de usuario", "explicacion": "0 flags fraude, 506d de antigüedad y 1 reclamo en 90d indican comportamiento conservador."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:19:51.453458');
