INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (73, 'COMP-0020', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y datos insuficientes para verificación automática, a pesar del perfil limpio del usuario.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por producto incorrecto en cuenta antigua sin historial de fraude, pero con evidencia GPS insuficiente para aprobación automática.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y datos insuficientes para verificación automática, a pesar del perfil limpio del usuario.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil limpio y antiguo", "explicacion": "antiguedad=609d, 0 flags fraude, 0 reclamos en 90d"}, {"peso": "medio", "señal": "Señal GPS perdida", "explicacion": "GPS no disponible impide corroborar entrega, generando ambigüedad"}, {"peso": "bajo", "señal": "Monto y ratio dentro de parámetros", "explicacion": "comp_ratio=0.867 y monto $499.49 no activan umbrales de riesgo"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:11:00.621283');
