INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (77, 'COMP-0021', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: alta frecuencia de reclamos, flag de fraude previo y naturaleza sensible del caso (riesgo de marca/salud) requieren validación humana de evidencia fotográfica y verificación de trazabilidad.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de producto caducado en cuenta con historial de alta frecuencia y flag de fraude, generando ambigüedad que requiere revisión manual.", "veredicto": "ESCALAR: alta frecuencia de reclamos, flag de fraude previo y naturaleza sensible del caso (riesgo de marca/salud) requieren validación humana de evidencia fotográfica y verificación de trazabilidad.", "señales_explicadas": [{"peso": "alto", "señal": "Alta frecuencia y ratio de compensación", "explicacion": "5 reclamos en 90d con comp_ratio 0.8092 indica patrón de uso intensivo de compensaciones."}, {"peso": "alto", "señal": "Flag de fraude previo", "explicacion": "1 flag de fraude registrado aumenta la probabilidad de abuso en reclamos posteriores."}, {"peso": "alto", "señal": "Riesgo de marca y salud", "explicacion": "Reclamo por producto caducado implica potencial intoxicación y daño reputacional, requiriendo revisión cuidadosa."}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "Falta de confirmación GPS reduce la trazabilidad del pedido, aunque el reclamo es sobre calidad del producto."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:11:23.29174');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (124, 'COMP-0027', 'reglas', 'RECHAZAR', 'RECHAZAR por señales de fraude: flags_fraude_previos >= 2.', 'flags_fraude_previos >= 2', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (216, 'COMP-0123', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Perfil de usuario altamente confiable (1589d antigüedad, 0 flags, baja frecuencia). Reclamo por producto incorrecto es coherente y el monto solicitado es razonable. La señal GPS perdida no genera contradicción.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por refresco equivocado en cuenta antigua sin historial de fraude. GPS sin señal pero sin inconsistencias operativas.", "veredicto": "APROBAR: reclamo legítimo con perfil conservador y sin señales de abuso o riesgo de marca.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario sano", "explicacion": "antiguedad=1589d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "bajo", "señal": "GPS señal perdida", "explicacion": "Falta de dato técnico que no contradice el reporte del usuario"}, {"peso": "medio", "señal": "Monto y frecuencia controlados", "explicacion": "comp_ratio=0.8978 y monto=$222.80 dentro de parámetros normales"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:20:35.727775');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (126, 'COMP-0038', 'reglas', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (82, 'COMP-SYN-0065', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: alta frecuencia de reclamos y ratio de compensación muy elevado requieren revisión humana para descartar abuso sistemático.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por producto dañado con alta frecuencia de compensaciones y monto cercano al valor total, generando ambigüedad sobre legitimidad.", "veredicto": "ESCALAR: alta frecuencia de reclamos y ratio de compensación muy elevado requieren revisión humana para descartar abuso sistemático.", "señales_explicadas": [{"peso": "alto", "señal": "Alta frecuencia de reclamos", "explicacion": "9 reclamos en 90 días indica un patrón inusual que puede sugerir uso sistemático de la política."}, {"peso": "alto", "señal": "Ratio de compensación elevado", "explicacion": "comp_ratio 0.9638 sugiere que el usuario recibe compensación en casi todos sus reclamos, lo cual es atípico."}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "La falta de confirmación GPS impide validar la entrega, añadiendo incertidumbre al caso."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:34:49.646737');
