INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (118, 'COMP-0031', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y reclamación de calidad alimentaria que requiere revisión humana para validación y gestión de riesgo.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por producto caducado en cuenta antigua sin historial de fraude, pero con evidencia GPS insuficiente.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y reclamación de calidad alimentaria que requiere revisión humana para validación y gestión de riesgo.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "0 flags de fraude, antigüedad de 1016d y baja frecuencia de reclamos"}, {"peso": "medio", "señal": "Señal GPS perdida", "explicacion": "Ausencia de geolocalización que impide corroborar el contexto de entrega"}, {"peso": "medio", "señal": "Reclamo de calidad alimentaria", "explicacion": "Afirmación de producto caducado que requiere verificación documental o física para evitar riesgos de marca"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:12:19.102563');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (221, 'COMP-0128', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y falta de evidencia concluyente, a pesar de perfil de usuario limpio.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por entrega no recibida con GPS perdido y perfil de usuario conservador. Caso ambiguo que requiere validación humana.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y falta de evidencia concluyente, a pesar de perfil de usuario limpio.", "señales_explicadas": [{"peso": "alto", "señal": "Señal GPS perdida", "explicacion": "La ubicación no confirma ni descarta la entrega, generando ambigüedad técnica."}, {"peso": "medio", "señal": "Perfil de usuario limpio", "explicacion": "0 flags de fraude, 353 días de antigüedad y 0 reclamos recientes reducen el riesgo de abuso."}, {"peso": "medio", "señal": "Ambigüedad en evidencia", "explicacion": "Reclamo basado en testimonio de vecino sin corroboración técnica, requiere análisis LLM/humano."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:21:25.096042');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (240, 'COMP-SYN-0068', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por falta de confirmación GPS y alta frecuencia de reclamos en 90 días requiere análisis humano.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por producto en mal estado sin evidencia GPS. Historial de antigüedad sólida pero con frecuencia de reclamos elevada en el último trimestre.", "veredicto": "ESCALAR: ambigüedad por falta de confirmación GPS y alta frecuencia de reclamos en 90 días requiere análisis humano.", "señales_explicadas": [{"peso": "alto", "señal": "GPS no confirmada", "explicacion": "Ausencia de geolocalización que valide la entrega, impidiendo corroborar el estado del producto automáticamente."}, {"peso": "medio", "señal": "Frecuencia de reclamos elevada", "explicacion": "6 reclamos en 90 días, lo que justifica revisión adicional a pesar de la antigüedad del usuario."}, {"peso": "bajo", "señal": "Perfil sin historial de fraude", "explicacion": "0 flags previos y 773 días de antigüedad indican comportamiento generalmente conservador."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:35:10.483693');
