INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (120, 'COMP-0033', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario antiguo (925d) con historial limpio y baja frecuencia de reclamos. La falta de confirmación GPS no contradice el reporte de no recepción. Monto y ratio dentro de parámetros normales, sin palabras críticas ni señales de abuso.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por retraso/no entrega en cuenta confiable sin inconsistencias verificables.", "veredicto": "APROBAR: reclamo legítimo con usuario de alto valor y sin indicadores de fraude o contradicción GPS.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=925d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "medio", "señal": "Ausencia de contradicción GPS", "explicacion": "GPS no confirmada, no invalida el reporte de no recepción"}, {"peso": "bajo", "señal": "Parámetros financieros normales", "explicacion": "monto $491.69 y comp_ratio 0.88 no superan umbrales de riesgo"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:12:41.700718');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (67, 'COMP-SYN-0009', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 1078 días de antigüedad y 0 flags de fraude. El reclamo corresponde a un error de cobro operativo (diferencia de precio) sin palabras críticas ni inconsistencias GPS relevantes para este tipo de incidencia. El historial es conservador y la solicitud se ajusta al monto real del error.', 'ambiguo: requiere análisis LLM', '{"resumen": "Error de cobro en restaurante Café Gourmet. Usuario antiguo y limpio solicita ajuste por diferencia de precio. Sin señales de fraude.", "veredicto": "APROBAR: reclamo legítimo de error de cobro en usuario con historial limpio y antigüedad superior a 3 años.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=1078d, flags_fraude=0, comp_ratio=0.8081 (dentro de rango seguro)"}, {"peso": "medio", "señal": "Naturaleza del reclamo", "explicacion": "Error de cobro operativo sin palabras críticas ni contradicciones de entrega"}, {"peso": "bajo", "señal": "Frecuencia moderada", "explicacion": "3 reclamos en 90d, pero compensado por antigüedad y ausencia de flags"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:25:27.213378');
