INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (91, 'COMP-SYN-0073', 'llm', 'RECHAZAR', 'RECHAZAR por análisis LLM: Alta frecuencia de reclamos (11 en 90d) combinada con inconsistencia crítica entre el monto declarado ($19 MXN) y el registrado en sistema ($196.40).', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por cobro excesivo y retraso con datos contradictorios y patrón de alta frecuencia en cuenta de antigüedad media.", "veredicto": "RECHAZAR: inconsistencia grave en el monto reclamado y densidad de reclamos anómala que indican posible abuso o error no validable.", "señales_explicadas": [{"peso": "alto", "señal": "Inconsistencia de monto", "explicacion": "El texto menciona $19 MXN pero el sistema registra $196.40 solicitado"}, {"peso": "alto", "señal": "Alta frecuencia de reclamos", "explicacion": "11 reclamos en 90 días con ratio de compensación del 91.2%"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "Ausencia de validación geoespacial para corroborar la interacción en tienda"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:35:31.821993');
