INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (128, 'COMP-0039', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 978 días de antigüedad y 0 flags de fraude. Reclamo por error de producto (refresco incorrecto) es coherente y no presenta inconsistencias GPS ni palabras críticas. Monto y frecuencia dentro de parámetros normales.', 'ambiguo: requiere análisis LLM', '{"resumen": "Error operativo de restaurante en usuario de larga antigüedad y perfil limpio. Sin señales de abuso o riesgo.", "veredicto": "APROBAR: reclamo legítimo consistente con evidencia disponible y perfil de usuario de bajo riesgo.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=978d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "medio", "señal": "Monto y frecuencia controlados", "explicacion": "comp_ratio=0.83, monto=$321.88, sin exceder umbrales de riesgo"}, {"peso": "bajo", "señal": "Coherencia del reclamo", "explicacion": "Error de producto sin contradicciones GPS ni términos críticos"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:13:04.871675');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (4, 'COMP-SYN-0010', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad en el reclamo y señal GPS perdida requieren validación humana para descartar fraude o error operativo.', 'ambiguo: requiere análisis LLM', '{"resumen": "Solicitud por producto erróneo con contenido atípico y GPS no verificable, sin historial de fraude previo.", "veredicto": "ESCALAR: ambigüedad en el reclamo y señal GPS perdida requieren validación humana para descartar fraude o error operativo.", "señales_explicadas": [{"peso": "alto", "señal": "Incoherencia del reclamo", "explicacion": "Menciona recibir una medicina en un restaurante, lo cual es atípico y genera duda sobre la legitimidad"}, {"peso": "medio", "señal": "Señal GPS perdida", "explicacion": "No permite confirmar la entrega o el estado del pedido, limitando la verificación automática"}, {"peso": "bajo", "señal": "Perfil sin historial de fraude", "explicacion": "0 flags y antigüedad de 190 días, pero insuficiente para aprobar ante la ambigüedad"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:25:46.832499');
