INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (94, 'COMP-SYN-0082', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por texto truncado, GPS no confirmada y señal de sistema que requiere análisis LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Solicitud de reembolso parcial por pedido incorrecto y falla en entrega. Sin evidencia GPS y con justificación incompleta, se requiere validación adicional.", "veredicto": "ESCALAR: ambigüedad por texto truncado, GPS no confirmada y señal de sistema que requiere análisis LLM.", "señales_explicadas": [{"peso": "alto", "señal": "Texto truncado", "explicacion": "El reclamo se corta abruptamente al mencionar la ubicación, impidiendo validar la coherencia completa del incidente."}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "Ausencia de geolocalización de entrega, lo que impide corroborar operativamente el reclamo."}, {"peso": "medio", "señal": "Señal de ambigüedad", "explicacion": "El motor de reglas detectó datos insuficientes y requiere análisis LLM para decisión final."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:36:42.77012');
