INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (133, 'COMP-0045', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 1706 días de antigüedad y 0 flags de fraude. Reclamo de discrepancia de cobro sin señales de abuso, con baja frecuencia y monto dentro de parámetros normales.', 'ambiguo: requiere análisis LLM', '{"resumen": "Discrepancia de cobro reportada por usuario de larga data sin historial de fraude. No aplica validación GPS al ser un error administrativo.", "veredicto": "APROBAR: reclamo legítimo de discrepancia de cobro en usuario con perfil conservador y sin indicadores de fraude.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=1706d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "medio", "señal": "Naturaleza del reclamo", "explicacion": "Discrepancia de cobro (error administrativo), no requiere validación GPS"}, {"peso": "bajo", "señal": "Monto y frecuencia controlados", "explicacion": "comp_ratio=0.7371, solicitado=$514.30, dentro de umbrales seguros"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:13:33.880041');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (40, 'COMP-SYN-0014', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: evidencia GPS no confirmada y frecuencia de reclamos moderada generan ambigüedad que requiere análisis LLM y revisión humana.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por retraso y falta de confirmación GPS en cuenta con historial moderado, requiere validación humana por ambigüedad en la evidencia.", "veredicto": "ESCALAR: evidencia GPS no confirmada y frecuencia de reclamos moderada generan ambigüedad que requiere análisis LLM y revisión humana.", "señales_explicadas": [{"peso": "alto", "señal": "Evidencia GPS ambigua", "explicacion": "GPS no confirmada y usuario reporta falta de confirmación, impidiendo validar la entrega o el retraso automáticamente"}, {"peso": "medio", "señal": "Frecuencia de reclamos", "explicacion": "6 reclamos en 90 días en cuenta de 602 días, sin flags de fraude pero con densidad que requiere contexto adicional"}, {"peso": "alto", "señal": "Requiere análisis LLM", "explicacion": "El sistema detectó ambigüedad que supera los umbrales de reglas automatizadas"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:26:59.737093');
