INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (153, 'COMP-0064', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y flag de fraude previo requiere revisión manual para validar discrepancia de cobro.', 'ambiguo: requiere análisis LLM', '{"resumen": "Discrepancia de monto con GPS no verificable y historial con flag de fraude.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y flag de fraude previo requiere revisión manual para validar discrepancia de cobro.", "señales_explicadas": [{"peso": "alto", "señal": "GPS señal perdida", "explicacion": "Impide verificación automática de la entrega y ubicación, generando incertidumbre."}, {"peso": "medio", "señal": "Flag de fraude previo", "explicacion": "1 flag en historial aumenta el riesgo de abuso en reclamos."}, {"peso": "medio", "señal": "Frecuencia de reclamos", "explicacion": "3 reclamos en 90d sugiere posible uso excesivo del sistema de compensaciones."}, {"peso": "alto", "señal": "Ambigüedad del reclamo", "explicacion": "Discrepancia de cobro sin evidencia adjunta requiere validación manual."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:14:31.58127');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (59, 'COMP-SYN-0003', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y frecuencia de reclamos elevada que requiere análisis humano para validar consistencia.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por cobro incorrecto con evidencia GPS perdida y historial de alta frecuencia de solicitudes en cuenta de antigüedad media.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y frecuencia de reclamos elevada que requiere análisis humano para validar consistencia.", "señales_explicadas": [{"peso": "alto", "señal": "Pérdida de señal GPS", "explicacion": "La evidencia de entrega es inconclusa, impidiendo verificar la ubicación real al momento del reclamo"}, {"peso": "medio", "señal": "Frecuencia elevada de reclamos", "explicacion": "6 reclamos en 90 días indica un patrón de alta demanda que requiere revisión de consistencia"}, {"peso": "bajo", "señal": "Discrepancia monetaria menor", "explicacion": "Diferencia de ~$18 MXN con ratio de compensación cercano a 1, sugiere posible error de sistema o disputa recurrente"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:25:04.052308');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (93, 'COMP-SYN-0017', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: evidencia GPS parcial y frecuencia moderada de reclamos requieren revisión humana para validar devolución y mitigar riesgo de marca.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por pedido incorrecto y retraso con GPS parcial, comp_ratio bajo y sin flags de fraude. Requiere validación humana por ambigüedad en la evidencia.", "veredicto": "ESCALAR: evidencia GPS parcial y frecuencia moderada de reclamos requieren revisión humana para validar devolución y mitigar riesgo de marca.", "señales_explicadas": [{"peso": "alto", "señal": "GPS Parcial", "explicacion": "La ubicación no confirma ni descarta la entrega/retiro, generando ambigüedad en la justificación del reclamo."}, {"peso": "medio", "señal": "Frecuencia de reclamos", "explicacion": "3 reclamos en 90 días con antigüedad de 236 días indica patrón moderado que requiere validación."}, {"peso": "alto", "señal": "Insuficiencia de evidencia", "explicacion": "El sistema detecta ambigüedad y requiere análisis LLM/humano para tomar decisión."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:27:18.299631');
