INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (60, 'COMP-SYN-0044', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad detectada y falta de confirmación GPS requieren revisión humana para validar la cancelación del restaurante.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por cancelación no notificada y retraso en cuenta limpia, con evidencia GPS insuficiente y señal de ambigüedad.", "veredicto": "ESCALAR: ambigüedad detectada y falta de confirmación GPS requieren revisión humana para validar la cancelación del restaurante.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil limpio", "explicacion": "0 flags fraude, 0 reclamos en 90d, antigüedad 110d"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "Evidencia geolocalización insuficiente para validar entrega o cancelación"}, {"peso": "alto", "señal": "Ambigüedad del sistema", "explicacion": "Señal automática indica requiere análisis LLM para decisión final"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:30:02.467137');
