INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (75, 'COMP-SYN-0095', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: alta frecuencia de reclamos en 90d genera ambigüedad que requiere análisis humano para validar patrón vs caso aislado.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por entrega con GPS de señal perdida. Cuenta antigua sin flags, pero con alta densidad de reclamos en 90 días.", "veredicto": "ESCALAR: alta frecuencia de reclamos en 90d genera ambigüedad que requiere análisis humano para validar patrón vs caso aislado.", "señales_explicadas": [{"peso": "alto", "señal": "Alta frecuencia de reclamos", "explicacion": "6 reclamos en 90 días, supera el umbral de normalidad y requiere revisión de patrón"}, {"peso": "bajo", "señal": "Coherencia GPS", "explicacion": "El sistema reporta señal perdida, coincidiendo con el reclamo, sin inconsistencia técnica"}, {"peso": "medio", "señal": "Perfil mixto", "explicacion": "Cuenta antigua (477d) y 0 flags de fraude, pero la densidad de reclamos justifica precaución"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:37:44.179593');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (160, 'COMP-0069', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 3+ años de antigüedad y 0 flags de fraude. Reclamo de cobro duplicado sin señales de abuso ni inconsistencias críticas.', 'ambiguo: requiere análisis LLM', '{"resumen": "Solicitud de reembolso por cobro duplicado en cuenta antigua y limpia, sin evidencia contradictoria.", "veredicto": "APROBAR: reclamo legítimo de cobro duplicado en usuario con historial limpio y antigüedad superior a 3 años.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=1226d, 0 flags fraude previos"}, {"peso": "medio", "señal": "Frecuencia y monto normales", "explicacion": "2 reclamos en 90d y monto solicitado $237.98 dentro de límites aceptables"}, {"peso": "bajo", "señal": "Ausencia de evidencia contradictoria", "explicacion": "GPS no confirmada no contradice cobro duplicado, sin palabras críticas ni reglas de riesgo activadas"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:14:54.049775');
