INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (162, 'COMP-0071', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: combinación de flag previo, alto ratio de compensación y señal de ambigüedad requieren revisión humana para descartar abuso encubierto.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por faltantes en pedido con historial mixto y ratio de compensación elevado, requiriendo validación manual.", "veredicto": "ESCALAR: combinación de flag previo, alto ratio de compensación y señal de ambigüedad requieren revisión humana para descartar abuso encubierto.", "señales_explicadas": [{"peso": "medio", "señal": "Historial mixto y alto ratio", "explicacion": "1 flag fraude, 4 reclamos en 90d y comp_ratio 0.91 sugieren uso frecuente del sistema que no supera umbrales automáticos pero requiere contexto."}, {"peso": "medio", "señal": "Evidencia GPS no disponible", "explicacion": "GPS NO confirmada impide validar la coherencia entre la entrega registrada y el reclamo de faltantes."}, {"peso": "alto", "señal": "Señal de ambigüedad", "explicacion": "El motor detecta incertidumbre y requiere análisis LLM/humano para evaluar la legitimidad del patrón de reclamos."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:15:32.335334');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (105, 'COMP-SYN-0018', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: cuenta nueva con alta frecuencia de reclamos y GPS no confirmada generan ambigüedad que requiere validación humana para descartar fraude o error operativo.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por entrega no verificada en cuenta nueva con alta densidad de solicitudes. Ausencia de corroboración GPS y patrón de comportamiento atípico.", "veredicto": "ESCALAR: cuenta nueva con alta frecuencia de reclamos y GPS no confirmada generan ambigüedad que requiere validación humana para descartar fraude o error operativo.", "señales_explicadas": [{"peso": "alto", "señal": "Cuenta nueva con alta frecuencia", "explicacion": "antiguedad=35d (<90d) con 6 reclamos en 90d, cumple regla de cuenta sospechosa"}, {"peso": "alto", "señal": "GPS no verificada", "explicacion": "La evidencia de ubicación no confirma la entrega, generando ambigüedad en la justificación"}, {"peso": "bajo", "señal": "Sin palabras críticas", "explicacion": "No se detectan términos de riesgo legal o sanitario, pero la ambigüedad operativa persiste"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:27:43.687933');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (61, 'COMP-SYN-0060', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por falta de confirmación GPS y patrón de reclamos en cuenta joven requiere validación humana para evitar riesgo de marca o fraude.', 'ambiguo: requiere análisis LLM', '{"resumen": "Solicitud de reembolso parcial por pedido incompleto sin evidencia GPS y con historial de reclamos moderado en cuenta joven.", "veredicto": "ESCALAR: ambigüedad por falta de confirmación GPS y patrón de reclamos en cuenta joven requiere validación humana para evitar riesgo de marca o fraude.", "señales_explicadas": [{"peso": "alto", "señal": "GPS no confirmada", "explicacion": "Ausencia de geolocalización que valide la entrega, factor determinante para verificar la existencia del reclamo."}, {"peso": "medio", "señal": "Frecuencia en cuenta joven", "explicacion": "3 reclamos en 90 días con 122 días de antigüedad, sin flags de fraude pero con densidad que requiere observación."}, {"peso": "bajo", "señal": "Justificación coherente sin evidencia", "explicacion": "Monto parcial solicitado y descripción lógica, pero la falta de datos objetivos genera ambigüedad operativa."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:33:50.34841');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (106, 'COMP-SYN-0098', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: frecuencia de reclamos elevada y naturaleza administrativa del reembolso requieren revisión humana para validar estado de cancelación y aplicar política correcta.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por reembolso de cancelación en cuenta con antigüedad sólida pero frecuencia elevada de solicitudes en 90 días.", "veredicto": "ESCALAR: frecuencia de reclamos elevada y naturaleza administrativa del reembolso requieren revisión humana para validar estado de cancelación y aplicar política correcta.", "señales_explicadas": [{"peso": "medio", "señal": "Frecuencia de reclamos", "explicacion": "6 reclamos en 90 días, lo que indica alta actividad de soporte a pesar de la antigüedad"}, {"peso": "medio", "señal": "Ambigüedad operativa", "explicacion": "Reclama reembolso por cancelación sin evidencia adjunta; GPS confirma entrega pero no valida estado de reembolso"}, {"peso": "bajo", "señal": "Perfil sin historial de fraude", "explicacion": "0 flags previos y 405d de antigüedad sugieren comportamiento no abusivo"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:38:02.997345');
