INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (163, 'COMP-0072', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'ESCALAR-1: Palabras críticas de seguridad de marca', '{"resumen": "Reclamo por error de ingrediente con mención de alergia en cuenta confiable. Requiere revisión por riesgo de salud.", "veredicto": "ESCALAR: contiene palabra crítica (''alergia'') que implica riesgo de salud y requiere revisión humana para validar evidencia.", "señales_explicadas": [{"peso": "alto", "señal": "Palabras críticas de seguridad de marca", "explicacion": "El reclamo menciona ''alergia'', término que activa protocolo de revisión humana por implicaciones de salud y riesgo de marca."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:15:46.102947');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (210, 'COMP-0116', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'ESCALAR-1: Palabras críticas de seguridad de marca', '{"resumen": "Reclamo por alergia en cuenta nueva con alta densidad de reclamos, flags de fraude y GPS confirmada. Activa regla de palabras críticas y señales de abuso.", "veredicto": "ESCALAR: contiene palabra crítica (''alergia'') que requiere revisión de seguridad de marca, sumado a un perfil de alto riesgo con cuenta nueva, alta frecuencia de reclamos y flags de fraude previos.", "señales_explicadas": [{"peso": "alto", "señal": "Palabras críticas", "explicacion": "El reclamo menciona ''alergia'', activando protocolo de seguridad de marca."}, {"peso": "alto", "señal": "Cuenta nueva con alta frecuencia", "explicacion": "Antigüedad de 10 días con 14 reclamos en 90 días."}, {"peso": "medio", "señal": "Historial de fraude", "explicacion": "2 flags de fraude previos y score de riesgo > 10.0."}, {"peso": "medio", "señal": "GPS confirmada", "explicacion": "La evidencia GPS confirma la entrega, lo que contrasta con la naturaleza del reclamo y sugiere posible inconsistencia."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:18:44.866779');
