INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (9, 'COMP-SYN-0026', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 1254 días de antigüedad y 0 flags de fraude. La frecuencia de reclamos es baja y la falta de confirmación GPS es coherente con la cancelación reportada. No se detectan palabras críticas ni patrones de abuso.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de reembolso por orden cancelada en cuenta antigua y sin historial de fraude, consistente con la evidencia GPS.", "veredicto": "APROBAR: reclamo legítimo, usuario confiable con historial limpio y evidencia GPS coherente con la cancelación.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=1254d, flags_fraude=0, frecuencia_baja"}, {"peso": "alto", "señal": "Consistencia GPS", "explicacion": "GPS no confirmada coincide con reporte de cancelación/no entrega"}, {"peso": "medio", "señal": "Monto coherente", "explicacion": "solicitado $396 vs orden $462, dentro de rangos normales"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:28:29.452076');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (164, 'COMP-0073', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con antigüedad superior a 4 años, 0 flags de fraude y baja frecuencia de reclamos. El reclamo por un refresco equivocado es un error operativo común y coherente. Aunque la señal GPS está perdida, el perfil altamente confiable y la naturaleza menor del reclamo no presentan indicios de fraude.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo menor por item incorrecto en usuario de alto perfil y sin historial de fraude. GPS perdida no invalida la legitimidad dada la trayectoria del usuario.", "veredicto": "APROBAR: reclamo legítimo y coherente respaldado por un perfil de usuario altamente confiable y sin señales de abuso.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=1580d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "medio", "señal": "Ambigüedad GPS", "explicacion": "Señal perdida en la entrega, pero mitigada por historial positivo y monto bajo"}, {"peso": "alto", "señal": "Naturaleza del reclamo", "explicacion": "Error de item común (refresco), monto solicitado razonable ($439.12) y sin palabras críticas"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:16:11.249181');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (132, 'COMP-SYN-0028', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: evidencia insuficiente y señal de ambigüedad requieren validación humana para confirmar entrega y monto.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con historial limpio y 199 días de antigüedad reporta pedido incompleto y sin confirmación GPS. No se detectan reglas de fraude activas, pero la evidencia es insuficiente para aprobación automática.", "veredicto": "ESCALAR: evidencia insuficiente y señal de ambigüedad requieren validación humana para confirmar entrega y monto.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario limpio", "explicacion": "0 flags de fraude, 0 reclamos en 90d, antigüedad 199d"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "No hay evidencia geolocalizada que respalde o contradiga el reclamo de no entrega"}, {"peso": "alto", "señal": "Ambigüedad en evidencia", "explicacion": "Sistema detecta insuficiencia de datos para decisión automatizada"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:28:47.726651');
