INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (222, 'COMP-0129', 'reglas', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (167, 'COMP-0076', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: GPS con señal perdida genera ambigüedad en la entrega, requiriendo revisión manual para validar evidencia adicional.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de no entrega con evidencia GPS incompleta en cuenta sana, generando ambigüedad operativa.", "veredicto": "ESCALAR: GPS con señal perdida genera ambigüedad en la entrega, requiriendo revisión manual para validar evidencia adicional.", "señales_explicadas": [{"peso": "alto", "señal": "GPS señal perdida", "explicacion": "La evidencia de ubicación no confirma la entrega, creando ambigüedad entre el estado de la app y el reclamo"}, {"peso": "medio", "señal": "Perfil de usuario sano", "explicacion": "0 flags fraude, antigüedad 532d, 1 reclamo en 90d, sin patrones de abuso"}, {"peso": "bajo", "señal": "Monto dentro de parámetros", "explicacion": "Solicitud de $320.68 no excede umbrales críticos de riesgo financiero"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:16:46.383635');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (10, 'COMP-SYN-0029', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por GPS sin señal y ratio de compensación elevado (0.927) en cuenta con 6 reclamos en 90d, requiere validación humana para confirmar legitimidad y evitar riesgo de marca.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por entrega no confirmada con GPS en señal perdida. Usuario antiguo sin flags, pero con alta frecuencia de reclamos y ratio de compensación cercano a 1.0. Se requiere revisión para validar la llamada del restaurante y el historial reciente.", "veredicto": "ESCALAR: ambigüedad por GPS sin señal y ratio de compensación elevado (0.927) en cuenta con 6 reclamos en 90d, requiere validación humana para confirmar legitimidad y evitar riesgo de marca.", "señales_explicadas": [{"peso": "alto", "señal": "GPS sin señal", "explicacion": "El estado del GPS coincide con el reclamo, pero al no haber confirmación de entrega, falta evidencia objetiva para aprobar automáticamente."}, {"peso": "medio", "señal": "Alta frecuencia y ratio de compensación", "explicacion": "6 reclamos en 90d y comp_ratio de 0.927 sugieren un historial de compensaciones muy activo que requiere revisión."}, {"peso": "bajo", "señal": "Perfil de usuario", "explicacion": "Antigüedad de 1158d y 0 flags de fraude reducen el riesgo, pero no anulan la ambigüedad por la falta de evidencia GPS."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:29:18.334579');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (229, 'COMP-0136', 'reglas', 'RECHAZAR', 'RECHAZAR por señales de fraude: flags_fraude_previos >= 2; freq_densidad > 0.66; flag_account_abuse.', 'flags_fraude_previos >= 2 | freq_densidad > 0.66 | flag_account_abuse', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
