INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (83, 'COMP-0024', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: GPS no confirmada y señal de ambigüedad requieren revisión humana para corroborar la entrega y el ítem faltante.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por ítem faltante en cuenta con perfil conservador, pero sin validación GPS y con señal de ambigüedad.", "veredicto": "ESCALAR: GPS no confirmada y señal de ambigüedad requieren revisión humana para corroborar la entrega y el ítem faltante.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario", "explicacion": "0 flags fraude, 325d antigüedad, 2 reclamos en 90d"}, {"peso": "alto", "señal": "GPS no confirmada", "explicacion": "La evidencia de ubicación no valida la entrega, generando ambigüedad"}, {"peso": "medio", "señal": "Señal de ambigüedad", "explicacion": "El sistema detecta insuficiencia de datos para decisión automatizada"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:11:54.642852');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (2, 'COMP-0053', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y datos insuficientes para validación automática.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de no recibido en cuenta limpia con evidencia GPS inconclusa.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y datos insuficientes para validación automática.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=1234d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "alto", "señal": "Evidencia GPS inconclusa", "explicacion": "Señal perdida impide confirmar entrega, generando ambigüedad"}, {"peso": "medio", "señal": "Reclamo coherente", "explicacion": "Justificación plausible sin palabras críticas ni inconsistencias"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:14:14.0849');
