INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (168, 'COMP-0077', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con antigüedad superior a 4 años y perfil completamente limpio (0 flags, 0 reclamos recientes). El reclamo por retraso es coherente y el monto solicitado está dentro de rangos normales. La pérdida de señal GPS es un factor técnico común que no invalida la queja por tiempo de entrega.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por retraso de entrega en cuenta antigua y sin historial de fraude. GPS perdido pero perfil de riesgo extremadamente bajo.", "veredicto": "APROBAR: reclamo legítimo respaldado por antigüedad y perfil limpio, sin señales de abuso.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de alto valor", "explicacion": "antiguedad=1634d, 0 flags fraude, 0 reclamos en 90d"}, {"peso": "medio", "señal": "Pérdida de señal GPS", "explicacion": "Señal perdida impide verificación exacta, pero es consistente con quejas por retraso en zonas con cobertura intermitente"}, {"peso": "bajo", "señal": "Monto y ratio dentro de norma", "explicacion": "comp_ratio=0.8055 y monto $238.65 no presentan anomalías estadísticas"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:17:05.936205');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (71, 'COMP-SYN-0046', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad en la evidencia (GPS no confirmada) y señal de análisis LLM requieren revisión humana para validar el error de cobro.', 'ambiguo: requiere análisis LLM', '{"resumen": "Solicitud de ajuste por diferencia de cobro en pedido reciente. Sin historial de fraude, pero sin confirmación GPS y con señal de ambigüedad.", "veredicto": "ESCALAR: ambigüedad en la evidencia (GPS no confirmada) y señal de análisis LLM requieren revisión humana para validar el error de cobro.", "señales_explicadas": [{"peso": "medio", "señal": "GPS no confirmada", "explicacion": "No hay evidencia geolocalizada que respalde la entrega, limitando la verificación automática."}, {"peso": "bajo", "señal": "Ratio de compensación moderado", "explicacion": "comp_ratio=0.8342 indica un historial de uso de compensaciones dentro de rangos normales pero no óptimos."}, {"peso": "alto", "señal": "Ambigüedad en datos", "explicacion": "Se detectó señal de ambigüedad que requiere análisis LLM para confirmar la coherencia del error de cobro."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:30:22.919429');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (1, 'COMP-0002', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'ESCALAR-1: Palabras críticas de seguridad de marca', '{"resumen": "Reclamo por alergia alimentaria con palabra crítica detectada. GPS parcial y historial con 1 flag no invalidan la necesidad de revisión especializada.", "veredicto": "ESCALAR: contiene la palabra crítica ''alergia'' que requiere revisión humana por implicaciones de salud y seguridad de marca.", "señales_explicadas": [{"peso": "alto", "señal": "Palabras críticas de seguridad de marca", "explicacion": "El usuario menciona ''alergia al lácteo'', activando la regla de escalación obligatoria."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 12:12:10.824547');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (250, 'COMP-0149', 'reglas', 'RECHAZAR', 'RECHAZAR por señales de fraude: flags_fraude_previos >= 2.', 'flags_fraude_previos >= 2', NULL, '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (3, 'COMP-SYN-0008', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.15): Cliente con historial limpio y antigüedad alta. El monto reclamado es ligeramente inferior al total pagado, lo que descarta intención de ganancia. La falta de GPS es una señal débil que no pesa más que el buen comportamiento histórico.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 457 días de antigüedad, 2 reclamos previos en 90 días y 0 flags de fraude. Reporta comida en mal estado y empaque roto. Solicita $162 de un total de $169. GPS no confirmada.", "veredicto": "APROBAR: El perfil del cliente es de bajo riesgo, el monto es razonable y no hay señales de fraude significativas.", "señales_explicadas": [{"peso": "alto", "señal": "Historial limpio", "explicacion": "0 flags de fraude y solo 2 reclamos en 90 días con 457 días de antigüedad indican un patrón de uso legítimo."}, {"peso": "medio", "señal": "Monto solicitado", "explicacion": "Solicita $162 de $169, una compensación casi total pero sin exceder el costo, lo cual es típico en quejas genuinas."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "La ubicación no pudo ser verificada, pero es una señal débil frente al resto del perfil."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (8, 'COMP-SYN-0022', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.35): Usuario con 6 reclamos en 90 días y antigüedad de solo 46 días indica patrón de quejas frecuentes, pero sin flags de fraude previos. El monto reclamado ($165 MXN) es bajo y típico de disputas por servicio. La pérdida de señal GPS es señal técnica ambigua. Se requiere validar logs de GPS y tiempo real de entrega.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario de Guadalajara con 46 días de antigüedad reclama sobrecargo de $165 MXN en pedido de $316 MXN a El Rincón Colombiano, reportando 76 minutos de entrega y pérdida de señal GPS. Acumula 6 reclamos en 90 días sin historial de fraude.", "veredicto": "APROBAR: Compensación por la diferencia de $165 MXN, sujeta a verificación de logs de GPS y timestamp de entrega. Si se confirma la interrupción de señal y el tiempo excedido, procede reembolso parcial.", "señales_explicadas": [{"peso": "alto", "señal": "Frecuencia de reclamos (6 en 90 días)", "explicacion": "Indica posible abuso de políticas de compensación o cliente de alto mantenimiento, aunque sin historial fraudulento."}, {"peso": "medio", "señal": "Pérdida de señal GPS", "explicacion": "Puede ser indicio de manipulación (modo avión) o falla técnica legítima; señal ambigua que requiere validación."}, {"peso": "medio", "señal": "Antigüedad de cuenta (46 días)", "explicacion": "Cuenta relativamente nueva con alta actividad de reclamos, lo que eleva ligeramente el riesgo de comportamiento oportunista."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (32, 'COMP-SYN-0056', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.15): Reclamo genuino con evidencia de error en producto entregado, cliente dispuesto a pagar diferencia, GPS confirmado y sin historial de fraude.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 24 días de antigüedad y 1 reclamo previo reporta haber recibido un kit de higiene para bebés en lugar del kit para embarazadas solicitado. Se le pidió pagar el 93% del monto original ($231 de $294). GPS confirma entrega.", "veredicto": "APROBAR: Error operativo en el armado del pedido, cliente actuó de buena fe al contactar soporte y aceptar pago parcial. Procede compensación o reenvío.", "señales_explicadas": [{"peso": "alto", "señal": "GPS confirmado", "explicacion": "La ubicación de entrega fue verificada, descartando reclamo por no recepción."}, {"peso": "alto", "señal": "Sin flags de fraude", "explicacion": "El cliente no tiene historial de comportamiento fraudulento en la plataforma."}, {"peso": "bajo", "señal": "Baja antigüedad", "explicacion": "24 días es un perfil relativamente nuevo, pero no presenta otras señales de riesgo."}, {"peso": "bajo", "señal": "1 reclamo en 90 días", "explicacion": "Frecuencia baja y normal para un usuario activo, no indica patrón abusivo."}, {"peso": "medio", "señal": "Disposición a pagar diferencia", "explicacion": "El cliente menciona que se le pidió cubrir el 93% del monto, lo cual aceptó, indicando intención de resolver legítimamente."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (5, 'COMP-SYN-0013', 'llm', 'RECHAZAR', 'RECHAZAR por análisis LLM: Alta frecuencia de reclamos (9 en 90d) en cuenta reciente con GPS no confirmada, lo que impide validar la entrega y sugiere patrón de abuso.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por cobro excesivo y entrega no rastreada en cuenta con densidad de solicitudes elevada.", "veredicto": "RECHAZAR: alta frecuencia de reclamos y falta de evidencia GPS en cuenta reciente indican posible abuso de compensaciones.", "señales_explicadas": [{"peso": "alto", "señal": "Alta frecuencia de reclamos", "explicacion": "9 reclamos en 90 días en cuenta de 119 días de antigüedad"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "Ruta de entrega sin geolocalización, impidiendo verificar coherencia temporal y de ubicación"}, {"peso": "bajo", "señal": "Antigüedad reciente", "explicacion": "Cuenta con 119 días, periodo aún vulnerable a patrones de abuso"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:26:36.615888');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (29, 'COMP-SYN-0049', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: cuenta nueva con flag de fraude, GPS no confirmada y descripción de falla técnica que requiere validación humana para descartar abuso o error operativo.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por calidad de comida en cuenta de reciente creación con historial de fraude leve y sin evidencia GPS. Caso ambiguo que requiere revisión.", "veredicto": "ESCALAR: cuenta nueva con flag de fraude, GPS no confirmada y descripción de falla técnica que requiere validación humana para descartar abuso o error operativo.", "señales_explicadas": [{"peso": "alto", "señal": "Cuenta nueva con flag", "explicacion": "antiguedad=18d y 1 flag de fraude previo, perfil de riesgo incipiente"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "Ausencia de evidencia geolocalizada para validar la entrega o el estado del pedido"}, {"peso": "medio", "señal": "Inconsistencia técnica en descripción", "explicacion": "Menciona productos con estados contradictorios (calientes/crudos, congelado en plato caliente) que requiere validación"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:31:04.087463');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (31, 'COMP-SYN-0052', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por GPS parcial y señal de requerimiento de análisis LLM, a pesar de no activar reglas de fraude.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por entrega parcial y falta de reembolso proporcional en cuenta con historial limpio y GPS inconclusa.", "veredicto": "ESCALAR: ambigüedad por GPS parcial y señal de requerimiento de análisis LLM, a pesar de no activar reglas de fraude.", "señales_explicadas": [{"peso": "alto", "señal": "GPS Parcial", "explicacion": "La evidencia de ubicación solo confirma entrega parcial, generando ambigüedad en el monto exacto a compensar"}, {"peso": "medio", "señal": "Historia limpia", "explicacion": "0 flags de fraude, 366 días de antigüedad y baja frecuencia de reclamos (2 en 90d)"}, {"peso": "alto", "señal": "Señal de ambigüedad", "explicacion": "El sistema detecta ambigüedad y requiere análisis LLM para validar la proporcionalidad del reembolso"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:32:11.827189');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (38, 'COMP-0007', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 655 días de antigüedad reporta producto caducado. Presenta solo 2 reclamos previos en 90 días y sin historial de fraude. La señal GPS se perdió durante la entrega.", "veredicto": "APROBAR: El reclamo es consistente con un problema de control de calidad del comercio, no con un patrón de abuso. El perfil del cliente es de bajo riesgo.", "señales_explicadas": [{"peso": "bajo", "señal": "Reclamos en 90d", "explicacion": "Solo 2 reclamos previos, frecuencia baja que no sugiere abuso sistemático."}, {"peso": "alto", "señal": "Antigüedad", "explicacion": "655 días como cliente activo, historial extenso que respalda su legitimidad."}, {"peso": "medio", "señal": "GPS Señal perdida", "explicacion": "Pérdida de señal durante la entrega, podría indicar un evento no rastreado, pero es insuficiente por sí solo para inferir fraude."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (47, 'COMP-0010', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por faltante de 2 tacos de un pedido de 5. Cliente con 1 reclamo en 90 días, 0 flags de fraude, antigüedad de 1656 días. GPS no confirmada.", "veredicto": "APROBAR: El perfil es de bajo riesgo y el reclamo es plausible.", "señales_explicadas": [{"peso": "alto", "señal": "antigüedad de cuenta", "explicacion": "1656 días de antigüedad indican un cliente estable y confiable."}, {"peso": "medio", "señal": "baja frecuencia de reclamos", "explicacion": "Solo 1 reclamo en 90 días, lejos de patrones de abuso."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "La falta de confirmación GPS no es determinante, ya que el faltante no depende de la ubicación."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (52, 'COMP-SYN-0004', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'ESCALAR-1: Palabras críticas de seguridad de marca', '{"resumen": "Cliente solicita reembolso de $666 MXN por pedido en Parrilla Clásica cancelado por el restaurante sin opción a rechazo, sin entrega del producto.", "veredicto": "APROBAR: Reembolso procedente por cancelación imputable al comercio, con trazabilidad verificable y perfil de usuario sin señales de fraude", "señales_explicadas": [{"peso": "medio", "señal": "Frecuencia de reclamos (8 en 90d)", "explicacion": "8 reclamos en 90 días representa una tasa superior al promedio pero dentro de rangos aceptables para usuario activo, sin exceder umbral de abuso (típicamente >12-15 en mismo período)"}, {"peso": "alto", "señal": "Historial limpio de fraude", "explicacion": "0 flags de fraude en 305 días de cuenta activa indica comportamiento consistente y sin intentos previos de defraudación"}, {"peso": "alto", "señal": "GPS confirmado", "explicacion": "Ubicación verificada en el momento del pedido, descartando suplantación de identidad o reclamo desde ubicación no coincidente"}, {"peso": "alto", "señal": "Cancelación por restaurante", "explicacion": "El tipo de incidencia es verificable contactando al comercio; si el restaurante canceló, el reembolso es automáticamente procedente según política de plataforma"}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (46, 'COMP-0008', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: perfil limpio pero señal de ambigüedad y datos insuficientes para validación automática de error de facturación.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por cobro duplicado en cuenta con historial conservador, pero con señal de ambigüedad que impide decisión automatizada.", "veredicto": "ESCALAR: perfil limpio pero señal de ambigüedad y datos insuficientes para validación automática de error de facturación.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario limpio", "explicacion": "0 flags de fraude y 312 días de antigüedad"}, {"peso": "medio", "señal": "Frecuencia y ratio moderados", "explicacion": "2 reclamos en 90d, comp_ratio 0.58, monto bajo"}, {"peso": "alto", "señal": "Ambigüedad en evidencia", "explicacion": "Sistema detecta ambigüedad y requiere análisis LLM para confirmar duplicidad"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:10:17.075905');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (39, 'COMP-SYN-0002', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por alta frecuencia de reclamos y falta de confirmación GPS requiere revisión humana.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por retraso/no entrega con evidencia GPS ausente en cuenta con alta frecuencia de solicitudes en 90 días.", "veredicto": "ESCALAR: ambigüedad por alta frecuencia de reclamos y falta de confirmación GPS requiere revisión humana.", "señales_explicadas": [{"peso": "alto", "señal": "Alta frecuencia de reclamos", "explicacion": "8 reclamos en 90 días indica un patrón de uso intensivo que requiere validación"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "La falta de confirmación geolocalizada impide verificar la entrega o el retraso"}, {"peso": "medio", "señal": "Perfil sin flags pero con densidad elevada", "explicacion": "0 flags previos pero alta actividad en 90d sugiere posible uso estratégico de reclamos"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:24:33.891514');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (41, 'COMP-SYN-0059', 'llm', 'RECHAZAR', 'RECHAZAR por análisis LLM: Cuenta nueva (15 días) con alta frecuencia de reclamos (5 en 90 días). La justificación del restaurante es operativamente incoherente y no hay evidencia GPS que respalde la cancelación.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de cuenta nueva con patrón de abuso y justificación irregular, sin soporte de evidencia.", "veredicto": "RECHAZAR: cuenta nueva con múltiples reclamos y justificación incoherente, indicando posible abuso sistemático.", "señales_explicadas": [{"peso": "alto", "señal": "Cuenta nueva con alta frecuencia", "explicacion": "antiguedad=15d, 5 reclamos en 90d"}, {"peso": "medio", "señal": "Justificación incoherente", "explicacion": "El restaurante alega cancelación por otro cliente sin confirmar cambios, patrón atípico"}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "Sin evidencia de ubicación que valide el estado del pedido"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:33:31.607858');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (51, 'COMP-SYN-0080', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por falta de confirmación GPS y necesidad de validar entrega parcial manualmente.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de entrega parcial sin confirmación GPS. Perfil conservador pero con evidencia insuficiente para decisión automática.", "veredicto": "ESCALAR: ambigüedad por falta de confirmación GPS y necesidad de validar entrega parcial manualmente.", "señales_explicadas": [{"peso": "alto", "señal": "GPS no confirmada", "explicacion": "La ubicación no valida la entrega, impidiendo corroborar si el pedido llegó o no."}, {"peso": "medio", "señal": "Perfil limpio sin abuso", "explicacion": "0 flags fraude, antigüedad >90d y baja frecuencia de reclamos descartan cuenta abusiva."}, {"peso": "bajo", "señal": "Reclamo de entrega parcial", "explicacion": "Solicitud de reembolso por productos faltantes requiere verificación de inventario o fotos del repartidor."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:36:27.220038');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (64, 'COMP-0013', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 843 días de antigüedad, solo 1 reclamo en 90 días, sin flags de fraude. Reporta cargo no revertido tras cancelación del restaurante. GPS no confirmada.", "veredicto": "APROBAR: Bajo riesgo de fraude, se recomienda compensar y verificar el reembolso con el comercio.", "señales_explicadas": [{"peso": "alto", "señal": "antigüedad de cuenta alta (843 días)", "explicacion": "Indica lealtad y reduce probabilidad de cuenta fraudulenta."}, {"peso": "medio", "señal": "solo 1 reclamo en 90 días", "explicacion": "Frecuencia baja de quejas, coherente con perfil genuino."}, {"peso": "alto", "señal": "0 flags de fraude", "explicacion": "Sin antecedentes ni alertas previas de comportamiento fraudulento."}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "Falta de coincidencia geográfica podría indicar sesgo pero no determina fraude por sí solo."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (65, 'COMP-0015', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 952 días de antigüedad reporta comida con olor a descompuesto. Solo 1 reclamo en 90 días y 0 flags de fraude. Entrega sin confirmación GPS, pero perfil general sugiere reclamo legítimo.", "veredicto": "APROBAR: Bajo riesgo de fraude por historial limpio y antigüedad, el incidente es plausible aunque falte evidencia de ubicación.", "señales_explicadas": [{"peso": "alto", "señal": "Frecuencia de reclamos", "explicacion": "Solo 1 reclamo en 90 días, muy por debajo de umbrales de abuso."}, {"peso": "alto", "señal": "Antigüedad de cuenta", "explicacion": "952 días de antigüedad indican usuario genuino y estable."}, {"peso": "alto", "señal": "Historial de fraude", "explicacion": "0 flags de fraude previas, sin patrones sospechosos."}, {"peso": "bajo", "señal": "Confirmación GPS", "explicacion": "GPS no confirmada, pero no es determinante dado el resto del perfil."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (68, 'COMP-0017', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 212 días de antigüedad reporta cargo no liberado tras cancelación del restaurante. GPS parcial, 6 reclamos en 90 días sin historial de fraude.", "veredicto": "APROBAR: El patrón es consistente con un problema operativo del comercio, no con abuso deliberado.", "señales_explicadas": [{"peso": "medio", "señal": "Reclamos en 90d (6)", "explicacion": "Frecuencia superior al promedio, pero sin indicios de fraude previo."}, {"peso": "bajo", "señal": "GPS Parcial", "explicacion": "La ubicación no es completamente verificable, pero no es un indicador determinante en este tipo de incidencia."}, {"peso": "bajo", "señal": "Antigüedad (212d)", "explicacion": "Cuenta con más de 7 meses, lo que reduce el riesgo de cuenta falsa o descartable."}, {"peso": "alto", "señal": "0 flags de fraude", "explicacion": "Sin antecedentes de comportamiento fraudulento, lo que respalda la legitimidad del reclamo."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (79, 'COMP-0022', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: alta frecuencia de reclamos y ambigüedad en la evidencia del error de cupón requieren revisión humana.', 'ambiguo: requiere análisis LLM', '{"resumen": "Solicitud de compensación por cupón no aplicado en cuenta con antigüedad estable y sin flags, pero con frecuencia elevada de reclamos.", "veredicto": "ESCALAR: alta frecuencia de reclamos y ambigüedad en la evidencia del error de cupón requieren revisión humana.", "señales_explicadas": [{"peso": "medio", "señal": "Alta frecuencia de reclamos", "explicacion": "5 reclamos en 90d sin flags previos, patrón que requiere validación"}, {"peso": "alto", "señal": "Ambigüedad en evidencia", "explicacion": "Error de cupón sin confirmación automática clara, requiere análisis LLM/humano"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:11:38.120389');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (76, 'COMP-SYN-0012', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por GPS no confirmado y retraso extremo requieren validación humana.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por no recepción con GPS pendiente y retraso de +3h. Evidencia insuficiente para decisión automática.", "veredicto": "ESCALAR: ambigüedad por GPS no confirmado y retraso extremo requieren validación humana.", "señales_explicadas": [{"peso": "alto", "señal": "GPS no confirmado", "explicacion": "La entrega no tiene registro GPS válido, lo que impide verificar la ubicación de entrega."}, {"peso": "medio", "señal": "Retraso crítico", "explicacion": "El pedido se realizó a las 5:45 p.m. y se reporta a las 8:58 p.m., un lapso de más de 3 horas que complica la verificación."}, {"peso": "bajo", "señal": "Perfil mixto", "explicacion": "Usuario antiguo (1036d) y sin flags, pero 2 reclamos en 90d con GPS pendiente generan incertidumbre operativa."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:26:10.13642');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (74, 'COMP-SYN-0063', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: cuenta nueva con flag de fraude previo y señal GPS perdida que impide verificación objetiva, requiriendo revisión humana.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por demora con GPS perdido en cuenta nueva con historial de fraude previo. Datos insuficientes para aprobación automatizada.", "veredicto": "ESCALAR: cuenta nueva con flag de fraude previo y señal GPS perdida que impide verificación objetiva, requiriendo revisión humana.", "señales_explicadas": [{"peso": "alto", "señal": "Cuenta nueva con reclamos", "explicacion": "antiguedad=36d (<90d) con 2 reclamos en 90d"}, {"peso": "alto", "señal": "Historial de fraude", "explicacion": "1 flag de fraude previo en la cuenta"}, {"peso": "medio", "señal": "GPS inconsistente", "explicacion": "Señal perdida impide corroborar la demora alegada de 48 min"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:34:11.349809');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (84, 'COMP-0025', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 6 reclamos en 90 días y 1 flag de fraude previo reporta doble cobro. La antigüedad de cuenta es de 348 días, pero el GPS parcial debilita la validación de ubicación.", "veredicto": "RECHAZAR: El patrón de reclamos frecuentes, el flag de fraude existente y la evidencia de ubicación incompleta sugieren un posible intento de compensación indebida.", "señales_explicadas": [{"peso": "alto", "señal": "Frecuencia de reclamos", "explicacion": "6 reclamos en 90 días supera el umbral normal, indicando posible comportamiento abusivo."}, {"peso": "alto", "señal": "Flag de fraude previo", "explicacion": "El usuario ya tiene 1 marcación por fraude, lo que incrementa la desconfianza."}, {"peso": "medio", "señal": "GPS parcial", "explicacion": "La información de ubicación incompleta impide verificar la entrega real, facilitando reclamos falsos."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (143, 'COMP-0056', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario reclama reembolso por cancelación de orden por falta de repartidor. En 90 días ha realizado 6 reclamos, tiene 1 flag de fraude y su ubicación GPS no fue confirmada.", "veredicto": "RECHAZAR: El perfil muestra múltiples indicadores de fraude, incluyendo alta frecuencia de reclamos y un flag previo, lo que sugiere un posible abuso del sistema de compensaciones.", "señales_explicadas": [{"peso": "alto", "señal": "Frecuencia de reclamos", "explicacion": "6 reclamos en 90 días, supera ampliamente el comportamiento normal"}, {"peso": "alto", "señal": "Flag de fraude previo", "explicacion": "El usuario ya ha sido marcado por fraude anteriormente"}, {"peso": "medio", "señal": "GPS no confirmado", "explicacion": "No se pudo verificar la ubicación de la entrega, lo que puede indicar suplantación"}, {"peso": "bajo", "señal": "Antigüedad de cuenta", "explicacion": "233 días de antigüedad, cuenta relativamente nueva pero con historial de reclamos"}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (235, 'COMP-0140', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: caso ambiguo por falta de confirmación GPS y contradicción con estado de la app, requiere validación manual.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de no recepción con GPS no confirmado y perfil de usuario sin historial de fraude, generando ambigüedad en la verificación.", "veredicto": "ESCALAR: caso ambiguo por falta de confirmación GPS y contradicción con estado de la app, requiere validación manual.", "señales_explicadas": [{"peso": "alto", "señal": "GPS no confirmado", "explicacion": "La evidencia geolocalizada no valida ni refuta la entrega, generando incertidumbre"}, {"peso": "medio", "señal": "Perfil de usuario", "explicacion": "Antigüedad de 911d y 0 flags de fraude, pero con 2 reclamos en 90d y ratio de compensación alto (0.955)"}, {"peso": "alto", "señal": "Ambigüedad en evidencia", "explicacion": "Contradicción entre estado de la app y reclamo sin soporte técnico verificable"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:23:19.104728');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (116, 'COMP-SYN-0025', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: alta frecuencia de reclamos (5 en 90d) sin confirmación GPS requiere revisión humana para validar consistencia y evitar riesgo de marca.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por no entrega con GPS no confirmada y patrón de frecuencia elevada en 90 días.", "veredicto": "ESCALAR: alta frecuencia de reclamos (5 en 90d) sin confirmación GPS requiere revisión humana para validar consistencia y evitar riesgo de marca.", "señales_explicadas": [{"peso": "medio", "señal": "Alta frecuencia de reclamos", "explicacion": "5 reclamos en 90 días sin flags de fraude previos"}, {"peso": "alto", "señal": "GPS no confirmada", "explicacion": "Ausencia de evidencia de entrega impide validación automática"}, {"peso": "medio", "señal": "Ambigüedad del caso", "explicacion": "El sistema detecta necesidad de análisis LLM para contexto logístico"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:28:04.287822');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (92, 'COMP-SYN-0075', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 1272 días de antigüedad, 0 flags y 0 reclamos recientes. Reclamo coherente sobre cobro excesivo y retraso. GPS no confirmada impide contradicción. Perfil altamente confiable.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por cobro incorrecto y retraso en cuenta antigua y limpia sin evidencia de fraude.", "veredicto": "APROBAR: reclamo consistente con perfil de usuario de alto valor y sin señales de abuso.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil confiable", "explicacion": "antiguedad=1272d, flags_fraude=0, reclamos_90d=0"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "No hay evidencia de entrega que contradiga el reclamo, favoreciendo al usuario"}, {"peso": "bajo", "señal": "Ambigüedad en cobro", "explicacion": "Discrepancia entre precio aplicado y solicitado requiere validación operativa"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:35:50.738634');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (95, 'COMP-SYN-0084', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por alta densidad de reclamos y flag previo requiere revisión humana para validar coherencia y riesgo de marca.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por comida en mal estado sin evidencia GPS, pero con historial de alta frecuencia y flag previo que impide decisión automatizada.", "veredicto": "ESCALAR: ambigüedad por alta densidad de reclamos y flag previo requiere revisión humana para validar coherencia y riesgo de marca.", "señales_explicadas": [{"peso": "alto", "señal": "Alta frecuencia de reclamos", "explicacion": "6 reclamos en 90d supera el comportamiento normal y sugiere posible patrón de abuso"}, {"peso": "medio", "señal": "Flag de fraude previo", "explicacion": "1 flag acumulado indica historial de riesgo que debe ser reevaluado"}, {"peso": "medio", "señal": "Ausencia de evidencia GPS", "explicacion": "La entrega no fue confirmada por GPS, lo que impide verificar la coherencia del reclamo de forma automatizada"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:37:00.170212');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (123, 'COMP-0036', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por comida con olor a descompuesto en un pedido entregado. Cliente con 367 días de antigüedad, 3 reclamos en los últimos 90 días, 1 marcado como fraude. Entrega con trazabilidad GPS parcial. Se detecta patrón de reclamos frecuentes y queja de calidad sin respaldo verificable.", "veredicto": "RECHAZAR: alta probabilidad de fraude por historial de reclamos frecuentes, antecedente de fraude y reclamación de calidad sin evidencia objetiva.", "señales_explicadas": [{"peso": "alto", "señal": "reclamos_frecuentes", "explicacion": "3 reclamos en 90 días indican un patrón de solicitud de compensaciones por encima de lo normal."}, {"peso": "alto", "señal": "flag_fraude_previo", "explicacion": "Antecedente de al menos un reclamo marcado como fraudulento, lo que reduce la confianza en el cliente."}, {"peso": "medio", "señal": "GPS_parcial", "explicacion": "Trazabilidad incompleta de la entrega dificulta la verificación del trayecto, aunque la queja no es por falta de entrega."}, {"peso": "medio", "señal": "queja_calidad_sin_evidencia", "explicacion": "Reclamación por comida descompuesta sin adjuntar fotos u otras pruebas, tipo de queja frecuentemente usado en fraudes."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (125, 'COMP-0037', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente antiguo con solo 1 reclamo previo en 90 días reporta espera de 90 minutos sin entrega. El repartidor no contestó y el GPS muestra pérdida de señal, lo que sugiere un incidente operativo/logístico genuino, no un intento de fraude por parte del usuario.", "veredicto": "APROBAR: El perfil del cliente es de altísima confianza y la evidencia contextual (GPS perdido) respalda un fallo en la entrega ajeno al usuario.", "señales_explicadas": [{"peso": "alto", "señal": "antiguedad_cliente", "explicacion": "1760 días de cuenta activa indican un usuario consolidado y de bajo riesgo."}, {"peso": "alto", "señal": "reclamos_previos", "explicacion": "Solo 1 reclamo en 90 días, muy por debajo del umbral de abusador frecuente."}, {"peso": "medio", "señal": "gps_perdida_señal", "explicacion": "La pérdida de señal GPS del repartidor justifica técnicamente la falta de comunicación y la no entrega, reduciendo la sospecha sobre el cliente."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (127, 'COMP-SYN-0027', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.15): Cliente con antigüedad de 586d y sin flags previos. El motivo (pérdida de señal GPS y demora de 64 min) es técnicamente plausible y consistente con el contexto dado. El monto reclamado ($143 MXN) es parcial y proporcional al pedido ($222 MXN). La frecuencia de 6 reclamos en 90d es ligeramente elevada pero no anómala para un usuario activo.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 586d de antigüedad reclama reembolso parcial de $143 MXN por pedido de $222 MXN cancelado tras demora de 64 minutos atribuida a pérdida de señal GPS. Sin historial de fraude.", "veredicto": "APROBAR: El reclamo es consistente con una falla técnica (GPS) y el monto es parcial, lo que reduce el riesgo. El perfil del usuario no muestra patrones de abuso.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad de cuenta (586d)", "explicacion": "Cuenta con historial extenso, lo que disminuye la probabilidad de fraude oportunista."}, {"peso": "alto", "señal": "0 flags de fraude previos", "explicacion": "Sin antecedentes de comportamiento fraudulento en el sistema."}, {"peso": "alto", "señal": "Reclamo por monto parcial ($143 de $222)", "explicacion": "Solicitar solo una parte del valor total es un comportamiento típico de reclamos legítimos, no de fraude que busca el reembolso completo."}, {"peso": "medio", "señal": "Frecuencia de reclamos (6 en 90d)", "explicacion": "Ligeramente superior al promedio, pero dentro de lo esperado para un usuario frecuente sin otros indicadores de riesgo."}, {"peso": "medio", "señal": "Motivo: Pérdida de señal GPS", "explicacion": "Falla técnica plausible y documentada en el contexto del delivery, que explica la demora y la cancelación."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (130, 'COMP-0041', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente reclama demora de más de 2 horas en una orden que prometía 30 minutos. Tiene solo 1 reclamo en 90 días, sin flags de fraude y cuenta de 1765 días. GPS no confirmada.", "veredicto": "APROBAR: Bajo riesgo de fraude por historial positivo, aunque la falta de GPS impide confirmación total.", "señales_explicadas": [{"peso": "alto", "señal": "Reclamo por demora", "explicacion": "El cliente reporta una demora significativa (2h vs 30min prometidos)."}, {"peso": "alto", "señal": "Baja frecuencia de reclamos", "explicacion": "Solo 1 reclamo en 90 días, indicando comportamiento no abusivo."}, {"peso": "alto", "señal": "Sin flags de fraude", "explicacion": "0 flags de fraude en el historial."}, {"peso": "alto", "señal": "Antigüedad de cuenta", "explicacion": "Cuenta con 1765 días de antigüedad, lo que sugiere un usuario legítimo."}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "No se pudo confirmar la ubicación de entrega, lo que dificulta verificar la demora."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (144, 'COMP-0057', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 373 días de antigüedad y solo 3 reclamos en 90 días reporta carne con color extraño. Sin flags de fraude previos. GPS parcial no es determinante. El reclamo es cualitativo y típico de insatisfacción genuina.", "veredicto": "APROBAR: Perfil de bajo riesgo, reclamo verosímil y sin patrones de abuso.", "señales_explicadas": [{"peso": "bajo", "señal": "3 reclamos en 90d", "explicacion": "Frecuencia baja, dentro de lo normal para un usuario activo."}, {"peso": "bajo", "señal": "0 flags fraude", "explicacion": "Sin historial de comportamiento fraudulento previo."}, {"peso": "bajo", "señal": "antiguedad 373d", "explicacion": "Cliente leal de más de un año, consistente con bajo riesgo."}, {"peso": "bajo", "señal": "GPS Parcial", "explicacion": "Datos de ubicación incompletos, pero no es una señal fuerte de fraude en reclamos de calidad."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (131, 'COMP-0042', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario reclama falta de salsas y cubiertos. Tiene 2 reclamos en 90 días, 1 flag de fraude, antigüedad 146 días y GPS parcial.", "veredicto": "RECHAZAR: Alta probabilidad de fraude por flag previo y señales de riesgo.", "señales_explicadas": [{"peso": "alto", "señal": "Flag de fraude previo", "explicacion": "El usuario ya fue marcado por fraude, lo que sugiere un patrón de comportamiento fraudulento."}, {"peso": "medio", "señal": "GPS parcial", "explicacion": "La señal GPS incompleta puede indicar manipulación de ubicación o problemas en la entrega."}, {"peso": "medio", "señal": "Reclamos en 90 días", "explicacion": "2 reclamos en 90 días es un volumen moderado que, combinado con otras señales, aumenta el riesgo."}, {"peso": "bajo", "señal": "Antigüedad de cuenta", "explicacion": "146 días es una antigüedad relativamente baja, lo que puede ser un factor de riesgo menor."}, {"peso": "bajo", "señal": "Tipo de reclamo", "explicacion": "Reclamo por artículos menores como salsas y cubiertos, común en fraudes de bajo monto."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (136, 'COMP-0048', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con cuenta de 1655 días reporta cancelación de orden por falta de repartidor sin reembolso. En 90 días ha realizado 2 reclamos, sin flags de fraude. GPS no confirmada.", "veredicto": "APROBAR: El reclamo es consistente con fallas operativas y el perfil del usuario no sugiere fraude.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad de cuenta (1655 días)", "explicacion": "Cuentas con larga antigüedad son menos propensas a fraude."}, {"peso": "medio", "señal": "0 flags de fraude", "explicacion": "El usuario no tiene historial de actividades fraudulentas."}, {"peso": "bajo", "señal": "2 reclamos en 90 días", "explicacion": "La frecuencia de reclamos es baja, no indica abuso."}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "No se pudo verificar la ubicación, pero la cancelación fue por falta de repartidor, no por ubicación."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (138, 'COMP-0050', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por monto incorrecto en resumen. Contexto: 2 reclamos en 90 días, 0 flags, antigüedad 306 días, GPS parcial.", "veredicto": "APROBAR: Se aprueba el reclamo por falta de evidencia contundente de fraude, aunque se recomienda verificar el GPS parcial.", "señales_explicadas": [{"peso": "medio", "señal": "GPS Parcial", "explicacion": "El GPS no registró la totalidad del recorrido, lo que dificulta la verificación de la entrega y puede indicar manipulación."}, {"peso": "bajo", "señal": "2 reclamos en 90 días", "explicacion": "Frecuencia de reclamos moderada, podría indicar un patrón de reclamos injustificados."}, {"peso": "alto", "señal": "0 flags de fraude", "explicacion": "El usuario no tiene antecedentes de fraude, lo que reduce la sospecha."}, {"peso": "bajo", "señal": "Antigüedad 306 días", "explicacion": "Usuario con casi un año en la plataforma, perfil de riesgo medio-bajo."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (139, 'COMP-0051', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 906 días de antigüedad, 0 flags y sin reclamos recientes. El reclamo por artículos faltantes es coherente con el monto solicitado y no presenta inconsistencias operativas ni señales de fraude.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo legítimo por omisión de salsas y cubiertos en cuenta con historial limpio y antigüedad superior a 2 años.", "veredicto": "APROBAR: reclamo consistente con usuario confiable y sin indicadores de abuso.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=906d, 0 flags fraude, 0 reclamos en 90d"}, {"peso": "medio", "señal": "Coherencia del reclamo", "explicacion": "Artículos faltantes justifican monto de $205.89 sin exceder ratios sospechosos"}, {"peso": "bajo", "señal": "GPS no aplicable", "explicacion": "La evidencia GPS no es relevante para reclamos de contenido faltante"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:13:52.389619');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (165, 'COMP-0074', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'ESCALAR-1: Palabras críticas de seguridad de marca', '{"resumen": "Reclamo por alergia alimentaria en cuenta con 1 flag previo y GPS no confirmada. La mención de riesgo de salud obliga a escalación.", "veredicto": "ESCALAR: contiene palabra crítica ''alergia'' que requiere validación humana y revisión de seguridad de marca.", "señales_explicadas": [{"peso": "alto", "señal": "Palabras críticas de seguridad de marca", "explicacion": "El usuario menciona ''alergia al lácteo'', activando la regla de escalación obligatoria por riesgo de salud y reputación."}, {"peso": "medio", "señal": "Historial con flag de fraude", "explicacion": "1 flag de fraude previo y 2 reclamos en 90 días, lo que añade cautela pero no anula la regla de palabras críticas."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:16:29.809123');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (141, 'COMP-SYN-0036', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: cuenta nueva con alta densidad de reclamos y caso ambiguo que requiere análisis LLM y revisión humana.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por diferencia de cobro y tiempo en cuenta nueva con múltiples solicitudes recientes.", "veredicto": "ESCALAR: cuenta nueva con alta densidad de reclamos y caso ambiguo que requiere análisis LLM y revisión humana.", "señales_explicadas": [{"peso": "alto", "señal": "Cuenta nueva con alta frecuencia", "explicacion": "antiguedad=18d, 5 reclamos en 90d, patrón sospechoso según reglas de negocio"}, {"peso": "medio", "señal": "Ambigüedad del reclamo", "explicacion": "Solicitud sobre cobro y tiempo requiere validación LLM y análisis de consistencia operativa"}, {"peso": "bajo", "señal": "GPS confirmada", "explicacion": "Entrega geolocalizada, descarta fraude de no entrega pero no resuelve la disputa de cobro"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:29:42.802918');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (149, 'COMP-SYN-0070', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.15): Cliente confiable con 0 reclamos en 90d, 0 flags y antigüedad alta. Señal de GPS perdida indica posible error técnico del repartidor. Monto solicitado ($421) es menor al total del pedido ($436), lo cual es atípico en fraudes.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 943 días de antigüedad, 0 reclamos previos y 0 flags de fraude reporta cancelación de pedido de $436 sin aviso ni reembolso. El GPS del delivery se perdió y la entrega tardó 46 minutos. Solicita reembolso de $421.", "veredicto": "APROBAR: Cliente legítimo con comportamiento consistente. La pérdida de señal GPS y cancelación sin aviso sugieren falla del repartidor, no fraude.", "señales_explicadas": [{"peso": "alto", "señal": "GPS señal perdida", "explicacion": "Indica interrupción del rastreo del repartidor, posible causa de la cancelación y no un intento de fraude por parte del cliente."}, {"peso": "medio", "señal": "Diferencia en monto reclamado", "explicacion": "Solicita $421 de $436, un error que un estafador evitaría al reclamar el total exacto, lo que sugiere honestidad."}, {"peso": "alto", "señal": "Historial limpio del cliente", "explicacion": "0 reclamos en 90 días, 0 flags de fraude y 943 días de antigüedad indican un usuario genuino sin patrones de abuso."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (154, 'COMP-0065', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 6 reclamos en 90 días y 1 flag de fraude previo reporta comida fría por llegada tarde, pero la señal GPS se perdió, lo que sugiere posible manipulación del dispositivo para simular un retraso no rastreable.", "veredicto": "RECHAZAR: El historial de reclamos frecuentes, el flag de fraude previo y la pérdida de señal GPS durante la entrega indican un posible abuso de compensaciones.", "señales_explicadas": [{"peso": "alto", "señal": "6 reclamos en 90d", "explicacion": "Frecuencia de reclamos muy superior al promedio, indicando posible abuso del sistema de compensaciones."}, {"peso": "alto", "señal": "1 flag fraude previo", "explicacion": "El usuario ya ha sido marcado por comportamiento fraudulento anteriormente."}, {"peso": "alto", "señal": "GPS Señal perdida", "explicacion": "La pérdida de señal impide corroborar la demora alegada y es una táctica común para simular retrasos."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (157, 'COMP-0066', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 1007 días de antigüedad, 2 reclamos en 90 días, 0 flags de fraude y GPS no confirmada. Reporta que no se aplicó un cupón activo, lo cual es un incidente operativo común.", "veredicto": "APROBAR: El perfil no presenta indicios de fraude; el reclamo es consistente y el riesgo es mínimo.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad de cuenta (1007 días)", "explicacion": "Cuenta con más de 2 años de vida, lo que reduce drásticamente la probabilidad de fraude."}, {"peso": "medio", "señal": "Historial de reclamos (2 en 90 días)", "explicacion": "Dos reclamos en tres meses es un volumen bajo y no sugiere abuso del sistema."}, {"peso": "alto", "señal": "0 flags de fraude", "explicacion": "Ningún antecedente de comportamiento fraudulento registrado."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "La falta de confirmación de ubicación añade una incertidumbre menor, pero no es suficiente para elevar el riesgo en este contexto."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (158, 'COMP-0067', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "El cliente reporta que solo recibió parte del pedido, faltando la bebida. La cuenta tiene 1666 días de antigüedad, 0 flags de fraude, aunque registra 2 reclamos en 90 días. La ubicación GPS no pudo ser confirmada, pero el tipo de incidencia es común en errores operativos.", "veredicto": "APROBAR: El reclamo es consistente con un faltante real, el perfil del cliente no muestra patrones de abuso y la falta de GPS no invalida la queja.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad de cuenta", "explicacion": "1666 días de antigüedad indican un cliente leal con bajo riesgo de fraude."}, {"peso": "medio", "señal": "Historial de reclamos", "explicacion": "2 reclamos en 90 días es una frecuencia ligeramente elevada, pero dentro de lo aceptable para un usuario activo."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "La imposibilidad de verificar la ubicación reduce la certeza, pero no es un indicador fuerte de fraude en este contexto."}, {"peso": "alto", "señal": "Tipo de incidencia", "explicacion": "Faltante de una bebida es un error operativo frecuente, no un patrón típico de fraude."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (161, 'COMP-0070', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 4+ años de antigüedad y 0 flags de fraude. El reclamo por cupón no aplicado es un error operativo común, sin señales de abuso. La pérdida de señal GPS es irrelevante para este tipo de incidencia.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo legítimo por error técnico en cupón de un usuario de alto perfil y baja frecuencia.", "veredicto": "APROBAR: reclamo consistente con perfil de usuario confiable y sin indicadores de fraude.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=1660d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "medio", "señal": "Tipo de incidencia operativa", "explicacion": "Error de cupón no aplicado es un fallo técnico común, no asociado a fraude"}, {"peso": "bajo", "señal": "GPS señal perdida", "explicacion": "Datos de ubicación no disponibles, pero irrelevantes para reclamo de cupón"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:15:09.843651');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (171, 'COMP-0082', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente antiguo reporta demora de 1.5h que inutilizó el pedido. Sin GPS no se puede confirmar el retraso, pero su historial limpio y baja recurrencia de quejas sugieren un incidente genuino.", "veredicto": "APROBAR: Perfil de bajo riesgo con antigüedad de 4+ años y solo 2 reclamos previos. La compensación procede como gesto de buena voluntad pese a la falta de evidencia GPS.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad alta (1598d)", "explicacion": "Cliente con más de 4 años en la plataforma, indicador de lealtad y bajo riesgo de fraude."}, {"peso": "alto", "señal": "Baja recurrencia de reclamos", "explicacion": "Solo 2 reclamos en 90 días, muy por debajo del umbral de abuso."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "Sin datos de geolocalización no se puede verificar el retraso, pero no es suficiente para denegar dado el perfil."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (174, 'COMP-0083', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 474 días de antigüedad reporta que el pedido figura como entregado pero su vecino niega que alguien haya tocado el timbre. Tiene solo 2 reclamos previos en 90 días, sin flags de fraude. La ubicación GPS no pudo ser confirmada.", "veredicto": "APROBAR: La falta de confirmación GPS no es suficiente para marcar como fraude dado el perfil confiable del cliente. Compensar por cortesía.", "señales_explicadas": [{"peso": "alto", "señal": "Reclamos en 90d", "explicacion": "Solo 2 reclamos previos, indicando que no es un usuario que reporte problemas con frecuencia."}, {"peso": "alto", "señal": "Antigüedad", "explicacion": "474 días de cuenta activa, lo que reduce la probabilidad de ser una cuenta creada para cometer fraude."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "La ubicación del repartidor no valida la entrega, pero esto puede deberse a falla de precisión o error del repartidor, no necesariamente fraude del cliente."}, {"peso": "alto", "señal": "Historial de fraude", "explicacion": "Cero flags de fraude previas, lo que refuerza la confiabilidad del usuario."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (176, 'COMP-0086', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente esperó 90 min, orden no llegó y repartidor no contestó. Historial: 2 reclamos en 90d, 0 flags, antigüedad 1222d, GPS perdido.", "veredicto": "APROBAR: El GPS perdido y el excelente historial del usuario respaldan la reclamación, baja probabilidad de fraude.", "señales_explicadas": [{"peso": "medio", "señal": "reclamos_previos", "explicacion": "2 reclamos en 90 días, frecuencia baja-moderada, no indica patrón abusivo."}, {"peso": "alto", "señal": "antiguedad_cuenta", "explicacion": "Cuenta con 1222 días de antigüedad (>3 años), señal de usuario legítimo y recurrente."}, {"peso": "alto", "señal": "flags_fraude", "explicacion": "0 flags de fraude en todo el historial."}, {"peso": "alto", "señal": "gps_perdida", "explicacion": "La señal GPS del repartidor se perdió, lo que es consistente con un posible incidente de entrega o manipulación, apoyando el reclamo del usuario."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (178, 'COMP-0088', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 522 días de antigüedad reporta faltante de papas fritas en su pedido. Solo registra 1 reclamo previo en 90 días sin flags de fraude. No hay confirmación de GPS.", "veredicto": "APROBAR: Perfil de bajo riesgo por antigüedad, baja recurrencia de reclamos y tipología de faltante común no asociada a fraude recurrente.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad del cliente (522d)", "explicacion": "Clientes con más de 1 año de antigüedad presentan menor tasa de fraude. Este perfil suma confianza."}, {"peso": "alto", "señal": "Baja recurrencia de reclamos (1 en 90d)", "explicacion": "Un solo reclamo en 3 meses indica comportamiento normal, sin patrón de abuso."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "La falta de confirmación GPS es relevante para ''no entrega'', pero no para faltantes de producto dentro de una orden recibida."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (180, 'COMP-0090', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y necesidad de verificar manualmente el estado de la orden y el proceso de reembolso.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por falta de reembolso tras cancelación por falta de repartidor, con evidencia GPS insuficiente que genera ambigüedad.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y necesidad de verificar manualmente el estado de la orden y el proceso de reembolso.", "señales_explicadas": [{"peso": "alto", "señal": "Señal GPS perdida", "explicacion": "La falta de datos de ubicación impide corroborar si la orden fue entregada, cancelada o si hubo error operativo."}, {"peso": "medio", "señal": "Perfil de usuario sano", "explicacion": "Antigüedad de 757 días, 0 flags de fraude y 1 reclamo en 90 días, indicando bajo riesgo de abuso."}, {"peso": "medio", "señal": "Ambigüedad operativa", "explicacion": "El motivo de cancelación y la falta de reembolso requieren revisión manual de logs de plataforma y pasarela de pagos."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:17:24.118962');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (241, 'COMP-SYN-0079', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por GPS parcial y datos insuficientes para validar cancelación sin notificación.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario reporta cancelación sin reembolso. GPS parcial y frecuencia moderada generan ambigüedad operativa.", "veredicto": "ESCALAR: ambigüedad por GPS parcial y datos insuficientes para validar cancelación sin notificación.", "señales_explicadas": [{"peso": "alto", "señal": "GPS Parcial", "explicacion": "La evidencia de ubicación no confirma ni descarta entrega/cancelación, generando incertidumbre."}, {"peso": "medio", "señal": "Frecuencia moderada en cuenta reciente", "explicacion": "2 reclamos en 90d con antigüedad de 104d, fuera de umbrales de abuso pero requiere monitoreo."}, {"peso": "bajo", "señal": "Ausencia de señales de fraude", "explicacion": "0 flags previos, comp_ratio bajo y monto dentro de rango, no indica patrón abusivo."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:36:09.382508');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (183, 'COMP-SYN-0071', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.30): Cliente con cuenta reciente (28d), sin historial de fraude. Reclamo no verificado (GPS no confirmada, sin evidencia), pero baja probabilidad de fraude intencional por monto bajo y único reclamo en 90 días.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente reporta pedido de 2 tacos de carnitas y 2 de pollo contaminados con insectos, solicita reembolso total ($422) o parcial ($262). Cuenta creada hace 28 días, GPS no confirmada, 0 flags de fraude previos.", "veredicto": "APROBAR: Aunque hay señales de precaución (cuenta nueva, geoposición no validada), el bajo monto, la falta de reincidencia y la naturaleza del reclamo no indican fraude manifiesto; se concede la compensación.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad de cuenta baja", "explicacion": "La cuenta tiene solo 28 días de creación, lo que eleva ligeramente el riesgo de fraude de primerizo."}, {"peso": "alto", "señal": "GPS no confirmada", "explicacion": "No se pudo validar la ubicación de entrega, lo que dificulta verificar que el pedido se recibió en la dirección declarada."}, {"peso": "medio", "señal": "Reclamo sin evidencia adjunta", "explicacion": "El cliente no proporciona fotos ni otros medios para corroborar la contaminación por insectos."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (184, 'COMP-0092', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 178 días de antigüedad reporta espera de 90 minutos y repartidor incomunicado. El GPS muestra pérdida de señal, lo cual es una táctica común para simular intento de entrega. El historial muestra 2 reclamos en 90 días y 1 flag de fraude previo, elevando el riesgo.", "veredicto": "RECHAZAR: El patrón de señal perdida más el historial de fraude sugiere un reclamo abusivo.", "señales_explicadas": [{"peso": "alto", "señal": "GPS Señal perdida", "explicacion": "El repartidor perdió la señal GPS, táctica frecuente para fingir un intento de entrega y reclamar compensación sin realizar el servicio."}, {"peso": "alto", "señal": "Historial de reclamos y flags", "explicacion": "El usuario acumula 2 reclamos en 90 días y ya tiene 1 flag de fraude, indicando un comportamiento reincidente."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (186, 'COMP-0094', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 1070 días de antigüedad reporta comida con olor a descompuesto. Solo 1 reclamo en 90 días, 0 flags de fraude. GPS no confirmada, pero no es crítica para este tipo de incidencia.", "veredicto": "APROBAR: Bajo riesgo de fraude, se sugiere compensar al cliente.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad de cuenta", "explicacion": "1070 días de antigüedad indican un cliente consolidado y de bajo riesgo."}, {"peso": "medio", "señal": "Volumen de reclamos", "explicacion": "Solo 1 reclamo en 90 días, frecuencia muy baja."}, {"peso": "alto", "señal": "Historial de fraude", "explicacion": "0 flags de fraude previos."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "La falta de confirmación GPS no es relevante para un reclamo por calidad del producto."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (188, 'COMP-0096', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 1280 días de antigüedad reporta faltante de 2/5 tacos. Solo 2 reclamos previos en 90 días, sin flags de fraude. GPS no confirmado.", "veredicto": "APROBAR: Perfil de bajo riesgo. La antigüedad y el historial limpio pesan más que la señal débil de GPS no confirmado.", "señales_explicadas": [{"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "No se pudo verificar la ubicación de entrega, pero es una señal débil en este contexto."}, {"peso": "alto", "señal": "Antigüedad alta (1280d)", "explicacion": "Cliente con más de 3 años en la plataforma, indicador de confianza."}, {"peso": "medio", "señal": "Bajo volumen de reclamos (2 en 90d)", "explicacion": "Frecuencia de reclamos dentro de lo normal, sin patrones de abuso."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (190, 'COMP-0098', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 170 días de antigüedad reporta cargo no reembolsado tras cancelación del restaurante. El GPS parcial no es determinante. Bajo riesgo.", "veredicto": "APROBAR: El reclamo es consistente con una cancelación iniciada por el comercio, donde el reembolso puede no haberse procesado automáticamente.", "señales_explicadas": [{"peso": "bajo", "señal": "5 reclamos en 90 días", "explicacion": "Frecuencia ligeramente elevada pero dentro de rangos aceptables para un usuario activo sin historial de fraude."}, {"peso": "alto", "señal": "0 flags de fraude", "explicacion": "Sin antecedentes de contracargos, abuso de promociones o comportamientos sospechosos previos."}, {"peso": "bajo", "señal": "GPS Parcial", "explicacion": "Común en pedidos cancelados donde la app deja de rastrear al no completarse la entrega. No es indicativo de fraude."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (194, 'COMP-0102', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 821 días de antigüedad, sin reclamos previos ni flags de fraude, reporta cancelación de orden por falta de repartidor sin reembolso. La señal GPS perdida sugiere un problema técnico o de cobertura del repartidor, no una acción maliciosa del cliente.", "veredicto": "APROBAR: El perfil del usuario y el contexto técnico (pérdida de señal GPS) respaldan la legitimidad del reclamo. Se recomienda proceder con el reembolso.", "señales_explicadas": [{"peso": "alto", "señal": "GPS Señal perdida", "explicacion": "La pérdida de señal del repartidor es una causa técnica frecuente que impide la entrega y deriva en cancelaciones, no es una acción del cliente."}, {"peso": "alto", "señal": "0 reclamos en 90d", "explicacion": "El usuario no presenta historial reciente de reclamos, lo que reduce la probabilidad de abuso."}, {"peso": "alto", "señal": "0 flags fraude", "explicacion": "Ningún antecedente de comportamiento fraudulento asociado a la cuenta."}, {"peso": "medio", "señal": "antiguedad 821d", "explicacion": "Cuenta con más de 2 años de actividad, lo que indica un cliente recurrente y de bajo riesgo."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (195, 'COMP-0103', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 541 días de antigüedad, 0 reclamos en 90 días y 0 flags de fraude reporta que cancelaron su pedido por falta de repartidor y no recibió reembolso. GPS de entrega no confirmada.", "veredicto": "APROBAR: Riesgo de fraude muy bajo; se autoriza el reembolso.", "señales_explicadas": [{"peso": "alto", "señal": "Historial de reclamos (0 en 90 días)", "explicacion": "El usuario no ha presentado reclamos recientes, lo que indica un comportamiento legítimo."}, {"peso": "alto", "señal": "Banderas de fraude (0)", "explicacion": "Ningún marcador de fraude previo, señal de confianza."}, {"peso": "medio", "señal": "Antigüedad de cuenta (541 días)", "explicacion": "Cuenta con más de un año de vida, consistente con un perfil genuino."}, {"peso": "bajo", "señal": "GPS de entrega no confirmada", "explicacion": "No se pudo verificar la ubicación de entrega, factor de riesgo leve."}, {"peso": "medio", "señal": "Motivo del reclamo (cancelación por falta de repartidor)", "explicacion": "La situación descrita es frecuente y justifica un reembolso; no hay indicios de abuso."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (196, 'COMP-0104', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 1397 días de antigüedad, solo 1 reclamo previo en 90 días y sin flags de fraude reporta un cargo no reembolsado tras cancelación del restaurante. La ubicación no fue confirmada por GPS.", "veredicto": "APROBAR: Usuario legítimo con bajo riesgo. El reclamo es consistente con una cancelación por parte del comercio donde el reembolso no se aplicó automáticamente.", "señales_explicadas": [{"peso": "alto", "señal": "antiguedad_cuenta", "explicacion": "1397 días de antigüedad indican un usuario establecido y de bajo riesgo."}, {"peso": "alto", "señal": "historial_reclamos", "explicacion": "Solo 1 reclamo en 90 días, sin flags de fraude previos, lo que sugiere un comportamiento normal."}, {"peso": "bajo", "señal": "gps_no_confirmada", "explicacion": "La falta de confirmación GPS es esperable si el restaurante canceló antes del envío, por lo que no es un indicador de fraude en este contexto."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (201, 'COMP-0109', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 244 días de antigüedad reporta producto incorrecto (pollo en lugar de res). Sin embargo, presenta 3 reclamos en 90 días, un flag de fraude previo y pérdida de señal GPS durante la entrega, lo que impide verificar la trazabilidad.", "veredicto": "RECHAZAR: El patrón de reclamos frecuentes, el antecedente de fraude y la evidencia de manipulación o fallo en el rastreo GPS sugieren un intento de abuso de las políticas de compensación.", "señales_explicadas": [{"peso": "alto", "señal": "Reclamos en 90 días", "explicacion": "3 reclamos en un trimestre indican una frecuencia de reportes superior a la media, lo que es un fuerte indicador de abuso."}, {"peso": "alto", "señal": "Flag de fraude previo", "explicacion": "El usuario ya ha sido marcado por fraude anteriormente, lo que establece un historial de comportamiento malicioso."}, {"peso": "alto", "señal": "GPS Señal perdida", "explicacion": "La pérdida de señal GPS durante la entrega puede indicar manipulación del dispositivo o un intento de ocultar la ubicación real para simular una entrega fallida o incorrecta."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (202, 'COMP-0110', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'flag_palabras_criticas: seguridad de marca', '{"resumen": "Usuario con 95 días de antigüedad reporta haber recibido una hamburguesa con queso pese a tener alergia a lácteos. Presenta 6 reclamos en 90 días, 1 flag de fraude previo y señal GPS perdida durante la entrega.", "veredicto": "RECHAZAR: Alta probabilidad de fraude por abuso de reclamos, historial previo y falta de evidencia de entrega incorrecta.", "señales_explicadas": [{"peso": "alto", "señal": "Frecuencia de reclamos (6 en 90d)", "explicacion": "Indica un patrón de abuso de compensaciones muy por encima del promedio."}, {"peso": "alto", "señal": "Flag de fraude previo", "explicacion": "El usuario ya ha sido marcado por comportamiento fraudulento anteriormente."}, {"peso": "medio", "señal": "GPS Señal perdida", "explicacion": "Imposibilita corroborar la ubicación real de entrega y si el pedido fue recibido."}, {"peso": "medio", "señal": "Alergia como motivo", "explicacion": "Reclamo basado en condición médica no verificable, común en fraudes por ser difícil de refutar."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (209, 'COMP-SYN-0077', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.15): Cliente con buen historial (0 reclamos, 334d antigüedad). El monto reclamado ($230) es coherente con el total del pedido ($252) menos el 18% que puede devolver. La falta de GPS es una señal débil que no pesa ante el perfil limpio.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 334 días de antigüedad y cero reclamos previos reporta haber recibido un producto incorrecto en un pedido de $252. Solo puede devolver el 18% del total, por lo que solicita $230 MXN como compensación. Sin flags de fraude previos.", "veredicto": "APROBAR: Perfil de bajo riesgo, monto coherente con el valor del pedido y la porción no devuelta, sin historial de abusos.", "señales_explicadas": [{"peso": "alto", "señal": "Historial limpio (0 reclamos en 90d, 0 flags fraude)", "explicacion": "El usuario nunca ha presentado reclamos ni ha sido marcado por fraude, lo que indica un comportamiento legítimo y reduce drásticamente la sospecha."}, {"peso": "alto", "señal": "Antigüedad de cuenta (334 días)", "explicacion": "Una cuenta con casi un año de vida es menos propensa a ser fraudulenta que cuentas nuevas creadas para abusar de compensaciones."}, {"peso": "medio", "señal": "Coherencia del monto reclamado", "explicacion": "El reclamo por $230 MXN es consistente con el valor total del pedido ($252) menos el 18% que el cliente afirma poder devolver (~$45), lo que sugiere un cálculo honesto."}, {"peso": "bajo", "señal": "GPS NO confirmada", "explicacion": "La falta de confirmación de GPS es una señal de alerta menor, pero en este contexto de perfil limpio y monto coherente, no es suficiente para indicar fraude."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (213, 'COMP-0120', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con historial limpio reporta faltantes de complementos (salsas y cubiertos), un reclamo típico de calidad/empaque sin patrones de abuso.", "veredicto": "APROBAR: reclamo de bajo riesgo por faltantes menores en cliente antiguo sin señales de fraude", "señales_explicadas": [{"peso": "alto", "señal": "Frecuencia de reclamos", "explicacion": "Solo 1 reclamo en 90 días, sin historial de abuso recurrente"}, {"peso": "medio", "señal": "Antigüedad del usuario", "explicacion": "731 días como cliente sin incidentes previos de fraude"}, {"peso": "medio", "señal": "Tipo de reclamo", "explicacion": "Faltantes de salsas/cubiertos son errores operativos comunes, no indican fraude estructurado"}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "Sin datos de ubicación pero no es determinante en reclamos por faltantes de complementos"}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (214, 'COMP-0121', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 198 días de antigüedad reclama falta de reembolso tras cancelación por ausencia de repartidor. Sin flags previos de fraude.", "veredicto": "APROBAR: El motivo es operativo y no hay señales de abuso de autoservicio. Procede reembolso.", "señales_explicadas": [{"peso": "bajo", "señal": "Frecuencia de reclamos (5 en 90d)", "explicacion": "Ligeramente elevada, pero sin historial de fraude previo, sugiere mala experiencia de usuario más que intención de estafa."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "Irrelevante para este caso, ya que la cancelación fue automática por falta de repartidor, no por disputa de entrega."}, {"peso": "bajo", "señal": "Antigüedad de cuenta (198d)", "explicacion": "Cuenta con historial suficiente para no ser considerada desechable, lo que reduce el riesgo."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (215, 'COMP-0122', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y reclamo subjetivo de calidad que requiere validación manual.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por calidad de alimento en cuenta antigua y sin historial de fraude, pero con señal GPS perdida que impide validación automática.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y reclamo subjetivo de calidad que requiere validación manual.", "señales_explicadas": [{"peso": "alto", "señal": "Señal GPS perdida", "explicacion": "La falta de coordenadas de entrega impide corroborar la ubicación y genera incertidumbre operativa."}, {"peso": "medio", "señal": "Perfil de usuario sano", "explicacion": "1775 días de antigüedad, 0 flags de fraude y solo 1 reclamo en 90 días indican comportamiento conservador."}, {"peso": "bajo", "señal": "Reclamo subjetivo de calidad", "explicacion": "La descripción del estado del alimento es difícil de verificar automáticamente sin evidencia adicional."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:20:12.589154');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (217, 'COMP-0124', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por señal GPS perdida y patrón de frecuencia elevada que impide verificación automática.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo de no recepción con GPS perdido y alta frecuencia de reclamos en cuenta con flag previo.", "veredicto": "ESCALAR: ambigüedad por señal GPS perdida y patrón de frecuencia elevada que impide verificación automática.", "señales_explicadas": [{"peso": "alto", "señal": "Señal GPS perdida", "explicacion": "No permite corroborar la ubicación de entrega, generando ambigüedad con el estatus de la app"}, {"peso": "medio", "señal": "Alta frecuencia de reclamos", "explicacion": "6 reclamos en 90 días con 1 flag previo indica posible abuso o patrón inusual"}, {"peso": "bajo", "señal": "Ambigüedad técnica", "explicacion": "Requiere análisis LLM/humano para evaluar coherencia entre reclamo y datos disponibles"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:21:01.840074');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (208, 'COMP-SYN-0055', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: evidencia GPS parcial combinada con alta frecuencia de reclamos (5 en 90d) genera ambigüedad que requiere análisis humano.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por empaque dañado con GPS parcial y alta frecuencia de reclamos en 90 días. La evidencia es insuficiente para decisión automatizada.", "veredicto": "ESCALAR: evidencia GPS parcial combinada con alta frecuencia de reclamos (5 en 90d) genera ambigüedad que requiere análisis humano.", "señales_explicadas": [{"peso": "alto", "señal": "GPS Parcial", "explicacion": "La ubicación de entrega no es completamente confirmada ni descartada, generando incertidumbre en la evidencia de la reclamación."}, {"peso": "medio", "señal": "Alta frecuencia de reclamos", "explicacion": "5 reclamos en los últimos 90 días, lo que indica un patrón de uso intensivo que requiere validación adicional."}, {"peso": "alto", "señal": "Señal de ambigüedad", "explicacion": "El sistema detecta ambigüedad en la evidencia disponible, lo que activa la regla de revisión manual según las directrices."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:32:53.068715');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (223, 'COMP-0130', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 576 días de antigüedad, 0 reclamos previos y 0 flags de fraude reporta discrepancia entre monto cobrado y resumen. No se confirma ubicación GPS.", "veredicto": "APROBAR: El perfil es de bajo riesgo y el reclamo parece legítimo. Se sugiere verificar el detalle de la transacción y resolver a favor del cliente.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad alta (576d)", "explicacion": "Clientes con más de un año de actividad suelen tener reclamos genuinos y baja intención de fraude."}, {"peso": "medio", "señal": "0 reclamos en 90 días", "explicacion": "Ausencia de historial reclamador reduce el riesgo de abuso del proceso de compensación."}, {"peso": "alto", "señal": "0 flags de fraude", "explicacion": "Sin marcas previas asociadas a comportamientos fraudulentos."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "Falta de validación de ubicación impide descartar suplantación o reclamo oportunista, pero por sí sola no eleva el riesgo en este perfil."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (239, 'COMP-0150', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 2 reclamos en 90 días y 1 flag de fraude reporta no recepción. La ubicación GPS del repartidor no confirma la entrega en la puerta, debilitando la defensa del repartidor.", "veredicto": "APROBAR: El reclamo es consistente con el perfil de riesgo del usuario y la falta de evidencia GPS impide validar la entrega.", "señales_explicadas": [{"peso": "alto", "señal": "Reincidencia en reclamos", "explicacion": "2 reclamos en 90 días indican un patrón de comportamiento inusual para un cliente legítimo."}, {"peso": "alto", "señal": "Flag de fraude previo", "explicacion": "El usuario ya tiene 1 marcación de fraude en el sistema, lo que eleva el riesgo de reincidencia."}, {"peso": "alto", "señal": "GPS no confirmada", "explicacion": "La falta de confirmación de ubicación del repartidor impide corroborar que estuvo en la dirección exacta."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (227, 'COMP-0134', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 790 días de antigüedad reporta faltante de 2/5 tacos. Solo 2 reclamos en 90 días, sin flags de fraude. La señal GPS perdida es la única señal atípica, pero no es concluyente de fraude.", "veredicto": "APROBAR: Perfil de bajo riesgo, reclamo consistente y proporcionado. La señal GPS no es suficiente para negar la compensación.", "señales_explicadas": [{"peso": "bajo", "señal": "GPS Señal perdida", "explicacion": "Pérdida de señal durante la entrega, posiblemente por zona de sombra o batería baja. No es un indicador fuerte de fraude sin otras señales."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (224, 'COMP-0131', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por alta frecuencia de reclamos, ratio de compensación elevado y evidencia GPS parcial requieren análisis LLM/humano.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por cargo pendiente tras cancelación de restaurante, con patrón de alta frecuencia y GPS parcial que requiere validación adicional.", "veredicto": "ESCALAR: ambigüedad por alta frecuencia de reclamos, ratio de compensación elevado y evidencia GPS parcial requieren análisis LLM/humano.", "señales_explicadas": [{"peso": "alto", "señal": "Alta frecuencia de reclamos", "explicacion": "5 reclamos en 90d con antigüedad de 306d y ratio de compensación del 0.86"}, {"peso": "alto", "señal": "Evidencia GPS parcial", "explicacion": "La ubicación no confirma ni descarta la entrega/cancelación, generando incertidumbre"}, {"peso": "medio", "señal": "Ambigüedad operativa", "explicacion": "Requiere análisis LLM para validar coherencia entre cancelación del restaurante y cargo pendiente"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:21:44.184494');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (225, 'COMP-0132', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad por falta de confirmación GPS y señal de requerir análisis LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por comida en mal estado en cuenta antigua sin evidencia GPS que respalde la entrega.", "veredicto": "ESCALAR: ambigüedad por falta de confirmación GPS y señal de requerir análisis LLM.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil confiable", "explicacion": "antiguedad=1260d, 0 flags fraude, 1 reclamo en 90d"}, {"peso": "medio", "señal": "Ambigüedad GPS", "explicacion": "GPS no confirmada, impide validar entrega o estado del pedido"}, {"peso": "bajo", "señal": "Requiere análisis LLM", "explicacion": "Sistema detecta ambigüedad y solicita revisión"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:22:08.577628');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (226, 'COMP-0133', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'ESCALAR-1: Palabras críticas de seguridad de marca', '{"resumen": "Reclamo por alergia alimentaria en cuenta antigua y sin historial de fraude, pero con señal GPS perdida y activación de regla de palabras críticas.", "veredicto": "ESCALAR: contiene palabra crítica (''alergia'') que requiere revisión humana para validar evidencia médica y cumplimiento del restaurante.", "señales_explicadas": [{"peso": "alto", "señal": "Palabras críticas de seguridad de marca", "explicacion": "El usuario menciona ''alergia'', activando la regla ESCALAR-1 por riesgo de salud y responsabilidad legal."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:22:20.260678');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (228, 'COMP-0135', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'ESCALAR-1: Palabras críticas de seguridad de marca', '{"resumen": "Reclamo por alergia en cuenta nueva con alta frecuencia de compensaciones y flags de fraude. GPS confirma entrega.", "veredicto": "ESCALAR: palabra crítica (''alergia'') requiere revisión humana por seguridad de marca, sumado a perfil de cuenta nueva con alta densidad de reclamos y flags de fraude.", "señales_explicadas": [{"peso": "alto", "señal": "Palabras críticas", "explicacion": "menciona ''alergia'', activando protocolo de seguridad de marca"}, {"peso": "alto", "señal": "Cuenta nueva con alta frecuencia", "explicacion": "antiguedad=23d, 12 reclamos en 90d"}, {"peso": "medio", "señal": "Historial de fraude", "explicacion": "flags_fraude_previos=2"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:22:38.652853');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (231, 'COMP-SYN-0005', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.15): Cliente con historial extenso (1414d) y solo 5 reclamos en 90d sin flags previos. La pérdida de GPS es un evento técnico plausible en Medellín. El monto reclamado ($361) es menor al total pagado ($414), lo que sugiere un reclamo parcial legítimo por producto incorrecto.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente antiguo reporta producto incorrecto en pedido de café gourmet y pérdida de señal GPS tras 37 min. Solicita reembolso parcial de $361 MXN de un total de $414 MXN.", "veredicto": "APROBAR: Cliente confiable con baja frecuencia de reclamos, sin historial de fraude. La pérdida de GPS es común en zonas urbanas densas y el reclamo parcial indica honestidad al no solicitar el monto total.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad de cuenta (1414 días)", "explicacion": "Cuenta con casi 4 años de actividad sin incidentes, indicador de cliente legítimo y de bajo riesgo."}, {"peso": "medio", "señal": "Baja frecuencia de reclamos (5 en 90 días)", "explicacion": "Promedio de 1.6 reclamos/mes para un usuario activo es aceptable y no muestra patrón abusivo."}, {"peso": "bajo", "señal": "Pérdida de señal GPS", "explicacion": "Evento técnico común en zonas con alta densidad urbana como Medellín, no necesariamente vinculado a manipulación fraudulenta."}, {"peso": "alto", "señal": "Reclamo por monto parcial ($361 de $414)", "explicacion": "Solicitar menos del total pagado sugiere reconocimiento parcial del servicio/producto y reduce sospecha de fraude."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (234, 'COMP-0139', 'llm', 'ESCALAR', 'ESCALAR por ambigüedad: las reglas no encuentran señales claras ni de fraude ni de legitimidad. Requiere análisis del texto del reclamo por LLM.', 'ambiguo: requiere análisis LLM', '{"resumen": "Repartidor reporta demora de 1.5 horas sobre lo estimado, resultando en comida en mal estado. El contexto muestra señal GPS perdida, lo que explica el retraso. Cliente con 5 reclamos en 90 días (frecuencia moderada-baja), sin historial de fraude y más de 10 meses de antigüedad.", "veredicto": "APROBAR: El retraso está justificado por la pérdida de señal GPS, indicando un problema técnico o de cobertura. El perfil del usuario no muestra patrones de abuso.", "señales_explicadas": [{"peso": "alto", "señal": "GPS Señal perdida", "explicacion": "La pérdida de señal GPS imposibilita la navegación y el tracking, causando demoras significativas. Es una señal técnica que respalda el reclamo."}, {"peso": "bajo", "señal": "5 reclamos en 90d", "explicacion": "Frecuencia de reclamo moderada-baja para un usuario activo. No alcanza umbrales típicos de abuso sistemático."}, {"peso": "medio", "señal": "0 flags fraude", "explicacion": "El usuario no tiene historial de marcado por fraude, lo que refuerza la legitimidad de sus reclamos previos."}, {"peso": "medio", "señal": "antiguedad 326d", "explicacion": "Antigüedad superior a 10 meses indica un usuario establecido, no una cuenta desechable creada para fraude."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (242, 'COMP-SYN-0081', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.15): Cliente con buen historial, antigüedad alta y sin señales de fraude previo. El monto es bajo y consistente con el inconveniente reportado.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 505 días de antigüedad, 1 reclamo en 90 días y 0 flags de fraude. Reporta pedido de Burger Express en Guadalajara entregado con 70 minutos de retraso y en mal estado. Solicita $121 MXN. GPS no confirmada.", "veredicto": "APROBAR: El perfil del cliente es de bajo riesgo, el monto es razonable y la falta de GPS no es determinante dado el buen historial.", "señales_explicadas": [{"peso": "alto", "señal": "Antigüedad alta (505d)", "explicacion": "Cliente con más de un año en la plataforma, lo que reduce la probabilidad de fraude."}, {"peso": "alto", "señal": "Baja frecuencia de reclamos", "explicacion": "Solo 1 reclamo en 90 días, sin historial de abuso del sistema de compensaciones."}, {"peso": "bajo", "señal": "GPS no confirmada", "explicacion": "No se pudo verificar la ubicación de entrega, pero el resto de señales son positivas."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (243, 'COMP-SYN-0097', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo (LLM score=0.50). Las reglas no fueron concluyentes y el LLM tampoco. Riesgo moderado por cuenta nueva y reclamos previos, pero sin señales de fraude confirmadas.', 'ambiguo: requiere análisis LLM', '{"resumen": "Usuario con 15 días de antigüedad reporta cancelación de pedido de $267 MXN sin acceso a su cuenta y sin reembolso de $224 MXN. Presenta 2 reclamos en 90 días, GPS parcial y cero flags de fraude.", "veredicto": "APROBAR: Compensar el reembolso pendiente con monitoreo adicional por perfil de riesgo.", "señales_explicadas": [{"peso": "medio", "señal": "Reclamos frecuentes", "explicacion": "2 reclamos en 90 días en una cuenta nueva"}, {"peso": "alto", "señal": "Antigüedad de cuenta", "explicacion": "Cuenta creada hace solo 15 días"}, {"peso": "bajo", "señal": "GPS parcial", "explicacion": "Datos de ubicación incompletos, posible inconsistencia"}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (244, 'COMP-SYN-0100', 'llm', 'APROBAR', 'APROBAR por análisis LLM (score=0.25): Cliente con historial limpio y antigüedad moderada, pero GPS parcial y reclamo por monto parcial específico sin alertas previas de fraude.', 'ambiguo: requiere análisis LLM', '{"resumen": "Cliente con 87 días de antigüedad, 2 reclamos previos sin flags de fraude, reporta cancelación de pedido de Sushi Fusión por $486 MXN sin reembolso parcial de $253 MXN. GPS parcial genera leve incertidumbre sobre ubicación, pero perfil general es de bajo riesgo.", "veredicto": "APROBAR: Cliente legítimo con historial sin marcas de fraude, monto reclamado coherente con cancelación parcial, y aunque GPS no es completo, no hay señales de abuso sistemático.", "señales_explicadas": [{"peso": "alto", "señal": "Historial del cliente", "explicacion": "2 reclamos en 90 días pero 0 flags de fraude, y 87 días de antigüedad indican cliente recurrente sin comportamiento abusivo"}, {"peso": "bajo", "señal": "GPS parcial", "explicacion": "La ubicación no pudo ser completamente verificada, lo que introduce leve duda sobre la ocurrencia del evento"}, {"peso": "alto", "señal": "Monto específico y consistente", "explicacion": "El reclamo por $253 MXN parcial de un total de $486 MXN es atípico en fraudes (suelen reclamar montos totales), sugiriendo un problema real de entrega/cancelación"}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (232, 'COMP-0137', 'llm', 'APROBAR', 'APROBAR por análisis LLM: Usuario con 3.6 años de antigüedad y historial limpio. Reclamo por producto faltante es coherente y no presenta contradicciones GPS ni señales de abuso.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo legítimo de ítem faltante en cuenta antigua y sin historial de fraude.", "veredicto": "APROBAR: reclamo consistente con perfil de usuario confiable y sin señales de fraude.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil confiable", "explicacion": "antiguedad=1320d, 0 flags fraude, 0 reclamos en 90d"}, {"peso": "medio", "señal": "Coherencia operativa", "explicacion": "Falta de ítem sin contradicción GPS ni palabras críticas de riesgo"}, {"peso": "bajo", "señal": "Monto y ratio razonables", "explicacion": "comp_ratio=0.7855 y monto solicitado dentro de parámetros normales"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:22:58.229694');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (247, 'COMP-0146', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'flag_palabras_criticas: seguridad de marca', '{"resumen": "Usuario con 246 días de antigüedad reporta recibir hamburguesa con queso alegando alergia al lácteo. Presenta 2 reclamos previos en 90 días y 2 flags de fraude previos, con GPS solo parcialmente validado.", "veredicto": "RECHAZAR: Patrón de abuso detectado. El tipo de reclamo (alergia no declarada previamente) combinado con historial de flags y GPS parcial sugiere fraude por auto-reporte para compensación.", "señales_explicadas": [{"peso": "alto", "señal": "Frecuencia de reclamos (2 en 90d)", "explicacion": "Tasa de reclamos anormalmente alta que excede el comportamiento típico de usuario legítimo."}, {"peso": "alto", "señal": "Flags de fraude previos (2)", "explicacion": "El usuario ya ha sido marcado por comportamiento sospechoso en ocasiones anteriores."}, {"peso": "medio", "señal": "GPS Parcial", "explicacion": "La geolocalización no puede ser completamente verificada, táctica común en fraudes para evitar detección."}, {"peso": "medio", "señal": "Naturaleza del reclamo (alergia)", "explicacion": "Alegar alergia a ingrediente común sin historial previo es táctica frecuente para obtener reembolso sin devolución."}]}', '2026-07-30 21:42:42.291114', '2026-07-30 21:42:42.291114');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (189, 'COMP-0097', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: cuenta nueva con múltiples reclamos y flag de fraude previo, sumado a GPS no confirmada, requiere revisión humana para validar legitimidad y evitar riesgo de marca.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por producto equivocado en cuenta nueva con historial de reclamos y flag previo, sin evidencia GPS para corroborar.", "veredicto": "ESCALAR: cuenta nueva con múltiples reclamos y flag de fraude previo, sumado a GPS no confirmada, requiere revisión humana para validar legitimidad y evitar riesgo de marca.", "señales_explicadas": [{"peso": "alto", "señal": "Cuenta nueva con frecuencia", "explicacion": "antiguedad=80d (<90d) con 3 reclamos en 90d, patrón sospechoso según reglas de negocio"}, {"peso": "medio", "señal": "Flag de fraude previo", "explicacion": "1 flag de fraude registrado, indica historial de riesgo aunque no supera el umbral de 2"}, {"peso": "medio", "señal": "GPS no confirmada", "explicacion": "Sin evidencia geolocalizada para validar o refutar la entrega, generando ambigüedad"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:17:43.355238');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (248, 'COMP-0147', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: ambigüedad en reclamo de discrepancia de cobro que requiere análisis manual de logs de transacción y validación de la evidencia.', 'ambiguo: requiere análisis LLM', '{"resumen": "Reclamo por diferencia en monto cobrado vs resumen. Usuario confiable pero caso ambiguo que requiere validación de datos de facturación.", "veredicto": "ESCALAR: ambigüedad en reclamo de discrepancia de cobro que requiere análisis manual de logs de transacción y validación de la evidencia.", "señales_explicadas": [{"peso": "alto", "señal": "Perfil de usuario confiable", "explicacion": "antiguedad=1612d, 0 flags fraude, 2 reclamos en 90d"}, {"peso": "alto", "señal": "Ambigüedad del reclamo", "explicacion": "Discrepancia de cobro sin evidencia adjunta, marcado como requiere análisis LLM"}, {"peso": "bajo", "señal": "Monto y ratio normales", "explicacion": "monto solicitado $230.51 y comp_ratio 0.6385 dentro de parámetros seguros"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:23:39.39138');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (249, 'COMP-0148', 'llm', 'ESCALAR', 'ESCALAR por seguridad de marca: el reclamo contiene palabras críticas que requieren revisión humana.', 'ESCALAR-1: Palabras críticas de seguridad de marca', '{"resumen": "Reclamo por alergia en cuenta nueva con alta frecuencia de compensaciones y evidencia GPS de entrega confirmada.", "veredicto": "ESCALAR: contiene palabra crítica (''alergia'') que requiere revisión humana por implicaciones de salud y marca, sumado a un perfil de alto riesgo con inconsistencias operativas.", "señales_explicadas": [{"peso": "alto", "señal": "Palabras críticas", "explicacion": "menciona ''alergia'', activando protocolo de seguridad de marca y salud"}, {"peso": "alto", "señal": "Cuenta nueva con alta frecuencia", "explicacion": "antiguedad=29d, 14 reclamos en 90d"}, {"peso": "medio", "señal": "Inconsistencia GPS", "explicacion": "GPS confirma entrega pero se reclama producto incorrecto/alergia"}, {"peso": "medio", "señal": "Historial de fraude", "explicacion": "2 flags de fraude previos y comp_ratio alto (0.95)"}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:24:06.540378');
INSERT INTO public.analisis_casos (id, caso_id, fuente, decision, justificacion, senales_usadas, llm_resultado, created_at, updated_at) VALUES (148, 'COMP-SYN-0048', 'llm', 'ESCALAR', 'ESCALAR: caso ambiguo. LLM: ESCALAR: alta frecuencia de reclamos combinada con señal GPS perdida genera ambigüedad que requiere revisión humana para validar la inconsistencia operativa.', 'ambiguo: requiere análisis LLM', '{"resumen": "Caso con ambigüedad por GPS perdido y alta frecuencia de reclamos en usuario antiguo, sin señales de fraude directo pero con datos insuficientes para decisión automatizada.", "veredicto": "ESCALAR: alta frecuencia de reclamos combinada con señal GPS perdida genera ambigüedad que requiere revisión humana para validar la inconsistencia operativa.", "señales_explicadas": [{"peso": "medio", "señal": "Alta frecuencia de reclamos", "explicacion": "8 reclamos en 90 días en cuenta de 1403 días, indica patrón inusual que requiere validación."}, {"peso": "alto", "señal": "Señal GPS perdida", "explicacion": "Imposibilidad de verificar ubicación y hora de entrega, genera ambigüedad técnica entre el reclamo y la evidencia."}, {"peso": "bajo", "señal": "Perfil mixto", "explicacion": "Cuenta antigua con 0 flags pero alta densidad de reclamos, no encaja en perfiles típicos de fraude ni de usuario sano."}]}', '2026-07-30 21:42:42.291114', '2026-07-31 02:30:42.765189');
