INSERT INTO public.resultados_reglas (id, caso_id, version_id, se_disparo, valor_actual, detalle, created_at) VALUES (4103, 'COMP-SYN-0051', 1, false, 'descripcion_reclamo=Hola, me dirijo a ustedes para quejarme porque la orden de la noche de ayer que hice a la tienda Los Tacos de Siempre, en Córdoba, no llegó nunca. Me hicieron un tiempo de entrega de 61 minutos, pero la verdad es que ya había agotado el tiempo de espera y no llegó nada, y pedí un valor de 151 pesos, se me ofrecen 124 pesos de compensación.', 'Palabras críticas de seguridad de marca no se disparó: descripcion_reclamo=Hola, me dirijo a ustedes para quejarme porque la orden de la noche de ayer que hice a la tienda Los Tacos de Siempre, en Córdoba, no llegó nunca. Me hicieron un tiempo de entrega de 61 minutos, pero la verdad es que ya había agotado el tiempo de espera y no llegó nada, y pedí un valor de 151 pesos, se me ofrecen 124 pesos de compensación. (contains_any [''alergi'', ''intoxic'', ''policía'', ''policia'', ''sangre'', ''insult'', ''denunci'', ''abogado'', ''demanda'', ''hospital'', ''veneno'']) ✗', '2026-07-31 02:31:51.999379');
