INSERT INTO public.resultados_reglas (id, caso_id, version_id, se_disparo, valor_actual, detalle, created_at) VALUES (3949, 'COMP-SYN-0013', 1, false, 'descripcion_reclamo=Soy un cliente del restaurante Parrilla Clásica que hice un pedido de entrega por un monto de $136 MXN. Resulta que en la entrega no se ajustó el cobro adecuadamente, ya que el monto que me cobraron fue $131 MXN más de lo que correspondía, y además la ruta GPS no fue confirmada con el tiempo de entrega de 59 minutos que había solicitado.', 'Palabras críticas de seguridad de marca no se disparó: descripcion_reclamo=Soy un cliente del restaurante Parrilla Clásica que hice un pedido de entrega por un monto de $136 MXN. Resulta que en la entrega no se ajustó el cobro adecuadamente, ya que el monto que me cobraron fue $131 MXN más de lo que correspondía, y además la ruta GPS no fue confirmada con el tiempo de entrega de 59 minutos que había solicitado. (contains_any [''alergi'', ''intoxic'', ''policía'', ''policia'', ''sangre'', ''insult'', ''denunci'', ''abogado'', ''demanda'', ''hospital'', ''veneno'']) ✗', '2026-07-31 02:26:36.597331');
INSERT INTO public.resultados_reglas (id, caso_id, version_id, se_disparo, valor_actual, detalle, created_at) VALUES (4114, 'COMP-SYN-0052', 1, false, 'descripcion_reclamo=Me contacto porque la orden que hice en Parrilla Clásica no llegó y no me reembolsaron el 84% del total que pagué, algunos detalles fueron el valor total del pedido $445 pesos, tiempo de entrega 76 minutos, la entrega solo registró una parcial. Me gustaría saber porque no me devolvieron mi dinero.', 'Palabras críticas de seguridad de marca no se disparó: descripcion_reclamo=Me contacto porque la orden que hice en Parrilla Clásica no llegó y no me reembolsaron el 84% del total que pagué, algunos detalles fueron el valor total del pedido $445 pesos, tiempo de entrega 76 minutos, la entrega solo registró una parcial. Me gustaría saber porque no me devolvieron mi dinero. (contains_any [''alergi'', ''intoxic'', ''policía'', ''policia'', ''sangre'', ''insult'', ''denunci'', ''abogado'', ''demanda'', ''hospital'', ''veneno'']) ✗', '2026-07-31 02:32:11.802003');
INSERT INTO public.resultados_reglas (id, caso_id, version_id, se_disparo, valor_actual, detalle, created_at) VALUES (4191, 'COMP-SYN-0064', 1, false, 'descripcion_reclamo=Estoy muy descontenta con la experiencia que nombre como cliente en su tienda, compré la comida en su Cevichería El Rey en Querétaro y resultó que la entrega llegó tardísima, 89 minutos después de realizada, y aunque esto ya es un problema en sí mismo, lo peor es que el problema llegó a casa sin ser confirmada la entrega por GPS. Me cobraron un total de $417, no sé qué', 'Palabras críticas de seguridad de marca no se disparó: descripcion_reclamo=Estoy muy descontenta con la experiencia que nombre como cliente en su tienda, compré la comida en su Cevichería El Rey en Querétaro y resultó que la entrega llegó tardísima, 89 minutos después de realizada, y aunque esto ya es un problema en sí mismo, lo peor es que el problema llegó a casa sin ser confirmada la entrega por GPS. Me cobraron un total de $417, no sé qué (contains_any [''alergi'', ''intoxic'', ''policía'', ''policia'', ''sangre'', ''insult'', ''denunci'', ''abogado'', ''demanda'', ''hospital'', ''veneno'']) ✗', '2026-07-31 02:34:31.359912');
