INSERT INTO public.resultados_reglas (id, caso_id, version_id, se_disparo, valor_actual, detalle, created_at) VALUES (4048, 'COMP-SYN-0044', 1, false, 'descripcion_reclamo=Me cancelaron mi pedido de $159 MXN en Cevichería El Rey en São Paulo sin que me advirtieran y sin reembolsar el monto, lo que me parece injusto. Me gustaría recibir un reembolso de $94 MXN por la cancelación de mi pedido, ya que no pude recibir la comida dentro del tiempo estimado de 58 minutos y no recibí confirmación de entrega por GPS.', 'Palabras críticas de seguridad de marca no se disparó: descripcion_reclamo=Me cancelaron mi pedido de $159 MXN en Cevichería El Rey en São Paulo sin que me advirtieran y sin reembolsar el monto, lo que me parece injusto. Me gustaría recibir un reembolso de $94 MXN por la cancelación de mi pedido, ya que no pude recibir la comida dentro del tiempo estimado de 58 minutos y no recibí confirmación de entrega por GPS. (contains_any [''alergi'', ''intoxic'', ''policía'', ''policia'', ''sangre'', ''insult'', ''denunci'', ''abogado'', ''demanda'', ''hospital'', ''veneno'']) ✗', '2026-07-31 02:30:02.449576');
INSERT INTO public.resultados_reglas (id, caso_id, version_id, se_disparo, valor_actual, detalle, created_at) VALUES (4169, 'COMP-SYN-0060', 1, false, 'descripcion_reclamo=Me llegó el pedido de la Cevichería El Rey en Buenos Aires el cual estaba incompleto, faltaba el arroz, lo que tuvo un costo de $457 MXN. Espero que me puedan devolver el dinero restante de $422 MXN, ya que no recibí lo que pague, por favor tramiten el reembolso a mi tarjeta de crédito lo antes posible".', 'Palabras críticas de seguridad de marca no se disparó: descripcion_reclamo=Me llegó el pedido de la Cevichería El Rey en Buenos Aires el cual estaba incompleto, faltaba el arroz, lo que tuvo un costo de $457 MXN. Espero que me puedan devolver el dinero restante de $422 MXN, ya que no recibí lo que pague, por favor tramiten el reembolso a mi tarjeta de crédito lo antes posible". (contains_any [''alergi'', ''intoxic'', ''policía'', ''policia'', ''sangre'', ''insult'', ''denunci'', ''abogado'', ''demanda'', ''hospital'', ''veneno'']) ✗', '2026-07-31 02:33:50.332492');
