-- Reset de secuencias para futuros inserts (re-análisis, nuevas versiones)
-- pg_dump fija search_path='' -> nombres completamente calificados.
SELECT pg_catalog.setval(pg_get_serial_sequence('public.analisis_casos','id'), COALESCE((SELECT MAX(id) FROM public.analisis_casos),1));
SELECT pg_catalog.setval(pg_get_serial_sequence('public.resultados_reglas','id'), COALESCE((SELECT MAX(id) FROM public.resultados_reglas),1));
SELECT pg_catalog.setval(pg_get_serial_sequence('public.reglas_versiones','version_id'), COALESCE((SELECT MAX(version_id) FROM public.reglas_versiones),1));
